const e=[{id:1,code:"HIS-INT-101",icon:"Landmark",accent:"#c9a227",title:"ما الدفاع المدني ولماذا وُجد",subtitle:"بداية المساق: حماية المدنيين من الحرائق والكوارث والحروب",summary:"الدفاع المدني هو مجموعة المهام الإنسانية التي تحمي المدنيين من خسائر الحرائق والكوارث والحروب ومعاناتها: الإنذار والإخلاء والملاجئ والإنقاذ والإسعافات الأولية ومكافحة الحرائق. يبيّن هذا الدرس لماذا نشأ هذا العمل، وكيف يعرض هذا المساق تاريخه مرحلةً بعد مرحلة.",facts:[{label:"1863–1864",value:"تأسيس اللجنة الدولية للصليب الأحمر واعتماد أول اتفاقية جنيف."},{label:"1931",value:"تأسيس جمعية «مناطق جنيف» في باريس لإيجاد ملاذات آمنة للمدنيين، وهي أصل المنظمة الدولية للحماية المدنية (ICDO)."},{label:"1949",value:"اعتماد اتفاقيات جنيف الأربع."},{label:"1977",value:"البروتوكول الإضافي الأول يمنح الدفاع المدني حماية خاصة وشارة دولية مميزة."},{label:"1 مارس",value:"اليوم العالمي للحماية المدنية؛ وفي 1 مارس 1972 دخل دستور المنظمة الدولية للحماية المدنية حيّز التنفيذ."},{label:"2013",value:"صدور قانون الدفاع المدني العراقي رقم 44."}],blocks:[{heading:"ما الدفاع المدني؟",body:"الدفاع المدني ليس جهازًا واحدًا فحسب، بل مجموعة من المهام هدفها حماية المدنيين وقت الخطر الكبير. تقول اللجنة الدولية للصليب الأحمر (ICRC) إن الدفاع المدني يهدف إلى التخفيف من الخسائر والأضرار والمعاناة التي تصيب المدنيين. وفي القانون الدولي الإنساني يُعرَّف الدفاع المدني بمهامه، لا باسم الجهة التي تؤديها؛ فكل من يُنذر الناس أو يُخليهم أو يطفئ حريقًا أو ينقذ جريحًا يؤدي مهمة من مهام الدفاع المدني."},{heading:"المهام الرئيسية",body:`حدّد البروتوكول الإضافي الأول (1977) خمس عشرة مهمة إنسانية، من أهمها:
• إنذار السكان قبل الخطر.
• إخلاء السكان من الأماكن الخطرة.
• تهيئة الملاجئ وإدارتها.
• الإنقاذ والبحث عن العالقين تحت المباني المنهارة.
• الخدمات الطبية والإسعافات الأولية.
• مكافحة الحرائق.
• المساعدة العاجلة في إعادة الخدمات الضرورية للحياة.`},{heading:"لماذا نشأ الدفاع المدني؟",body:"منذ القدم دمّرت الحرائق والفيضانات والزلازل المدن مرات كثيرة، فتعلّم الناس أن الحماية تحتاج إلى تنظيم: حراسة وإنذار وفرق جاهزة. ثم جاءت حروب القرن العشرين فجعلت الطائرات والقنابل المدنَ والمدنيين هدفًا، فنظّمت الدول الحماية من الغارات الجوية: صفارات الإنذار والملاجئ والتعتيم والمراقبون المتطوعون. وبعد الحرب أصبحت هذه التجربة أساس أجهزة الدفاع المدني الحالية التي تعمل في مواجهة جميع أنواع الكوارث."},{heading:"من الحرب إلى جميع المخاطر",body:"اليوم لم يعد الدفاع المدني مقتصرًا على زمن الحرب؛ ففي دول كثيرة يعمل في مواجهة الحرائق والفيضانات والزلازل وحوادث الطرق وتسرّب الغاز والمواد الخطرة. فمثلًا أُنشئت الوكالة الفيدرالية لإدارة الطوارئ (FEMA) في الولايات المتحدة عام 1979، وأُسندت إليها مهمتان معًا: إدارة الطوارئ والدفاع المدني. والمنظمة الدولية للحماية المدنية (ICDO) منظمة حكومية دولية تساعد الدول على بناء أجهزة حماية السكان."},{heading:"الدفاع المدني في العراق وإقليم كوردستان",body:"في العراق يوجد قانون الدفاع المدني رقم 44 لسنة 2013، وبحسب نصه فإن وزير الداخلية هو الرئيس الأعلى للدفاع المدني. وفي إقليم كوردستان يتبع الدفاع المدني وزارة الداخلية، ولكل محافظة مديرية للدفاع المدني، مثل مديرية الدفاع المدني في دهوك. وتعمل أقسامها في الإطفاء والإنقاذ البري والمائي والإسعافات الأولية والمواد الخطرة والوقاية والتوعية. ورقم الطوارئ هو 115. وسيبيّن هذا المساق كيف تطوّر هذا العمل عبر التاريخ."},{heading:"مسار هذا المساق",body:`يسير هذا المساق وفق ترتيب التاريخ، ويُبنى كل درس على الذي قبله:
1. ما الدفاع المدني ولماذا وُجد.
2. الحماية المبكرة للمدن: حراسة الحرائق والإطفاء القديم والإغاثة في الكوارث.
3. الحرب العالمية الأولى وبداية الحماية من الغارات الجوية.
4. الحرب العالمية الثانية: الملاجئ والتعتيم والمراقبون والمتطوعون.
5. الحرب الباردة: صفارات الإنذار والملاجئ والتخطيط.
6. القانون الدولي الإنساني وحماية الدفاع المدني.
وفي نهاية كل درس اسأل: ماذا تعلّمنا هذه التجربة اليوم؟`}],warnings:["الدفاع المدني ليس قوة قتالية: عمله إنساني ولا يجوز استخدامه لأغراض عسكرية.","لا تنشر معلومات غير موثّقة عن التاريخ المحلي: اسأل مديرية الدفاع المدني عن الحقائق."],tips:["احفظ الرقم 115 وعلّمه لأسرتك.","عند قراءة كل درس تاريخي اسأل: كيف يحمي هذا الدرس الناس اليوم؟","في 1 مارس، اليوم العالمي للحماية المدنية، شارك في أنشطة التوعية."],activity:{prompt:"يقول لك صديق: «الدفاع المدني هم فقط من يطفئون الحرائق». بماذا تجيبه؟",options:[{text:"الدفاع المدني مجموعة مهام: الإنذار والإخلاء والملاجئ والإنقاذ والإسعافات الأولية ومكافحة الحرائق.",correct:!0,feedback:"صحيح: القانون الدولي يعرّف الدفاع المدني بمهامه الإنسانية."},{text:"صحيح، عملهم الحرائق فقط ولا مهام أخرى لهم.",correct:!1,feedback:"مكافحة الحرائق واحدة فقط من خمس عشرة مهمة؛ والإنقاذ والإخلاء والإسعاف من مهامه أيضًا."},{text:"الدفاع المدني قوة عسكرية للقتال.",correct:!1,feedback:"لا: عمله إنساني لحماية المدنيين، لا للقتال."},{text:"الدفاع المدني يعمل في زمن الحرب فقط.",correct:!1,feedback:"لا: يعمل اليوم أيضًا في الحرائق والفيضانات والزلازل والحوادث."}]},caseStudy:[{prompt:"تريد مدرستك إعداد معرض عن تاريخ الدفاع المدني، وأنت مسؤول عن قسم «لماذا وُجد الدفاع المدني». بماذا يبدأ المعرض؟",options:[{text:"بالهدف: حماية المدنيين من خسائر الحرائق والكوارث والحروب ومعاناتها.",correct:!0,feedback:"صحيح: الهدف هو المحور الذي يربط التاريخ كله."},{text:"بصور المعدات الحديثة دون شرح الهدف.",correct:!1,feedback:"المعدات مهمة، لكنها دون الهدف لا تبيّن سبب وجود هذا العمل."},{text:"بقصة محلية غير موثّقة عن حريق قديم.",correct:!1,feedback:"لا تصلح المعلومات غير الموثّقة؛ فالتاريخ يحتاج إلى مصادر رسمية."}]},{prompt:"بعد الهدف، يقول المعلم إن شارة الدفاع المدني ومهامه يجب أن تكون على الجدار. أي طريقة صحيحة؟",options:[{text:"مثلث أزرق على خلفية برتقالية، وقائمة المهام الرئيسية من بروتوكول 1977.",correct:!0,feedback:"صحيح: هذه هي الشارة الدولية للدفاع المدني وفق البروتوكول الأول."},{text:"صليب أحمر على خلفية بيضاء بوصفه شارة الدفاع المدني.",correct:!1,feedback:"الصليب الأحمر شارة الخدمات الطبية والحركة، لا الدفاع المدني."},{text:"أي شعار جميل يختاره الطلاب.",correct:!1,feedback:"الشارة الدولية محددة بالقانون ولا تُستبدل بشعار آخر."}]}],quiz:[{question:"وفق القانون الدولي الإنساني، بماذا يُعرَّف الدفاع المدني؟",options:[{text:"بمهامه الإنسانية.",correct:!0},{text:"بلون ملابس منتسبيه.",correct:!1},{text:"بعدد سيارات الإطفاء.",correct:!1}],explanation:"تقول اللجنة الدولية إن الدفاع المدني يُعرَّف بمهامه لا باسم الجهة."},{question:"ما الهدف الرئيسي للدفاع المدني؟",options:[{text:"التخفيف من خسائر المدنيين ومعاناتهم.",correct:!0},{text:"حماية المباني الحكومية وحدها.",correct:!1},{text:"القتال ضد قوات العدو.",correct:!1}],explanation:"الدفاع المدني عمل إنساني يحمي المدنيين وليس عملًا قتاليًا."},{question:"كم مهمة للدفاع المدني يحدّد البروتوكول الإضافي الأول؟",options:[{text:"خمس عشرة مهمة.",correct:!0},{text:"ثلاث مهام.",correct:!1},{text:"خمس مهام.",correct:!1}],explanation:"تقول اللجنة الدولية إن البروتوكول يحصر الدفاع المدني في خمس عشرة مهمة مثل الإنذار والإخلاء والإنقاذ."},{question:"شبّ حريق في سوق. أيّ هذه الأعمال ليس من مهام الدفاع المدني؟",options:[{text:"تحديد أسعار بضائع السوق.",correct:!0},{text:"إخلاء الناس من السوق.",correct:!1},{text:"الإسعافات الأولية للمصابين.",correct:!1}],explanation:"الإخلاء والإسعافات الأولية من مهام البروتوكول؛ أما الأسعار فليست من عمل الدفاع المدني."},{question:"متى يوافق اليوم العالمي للحماية المدنية؟",options:[{text:"1 مارس.",correct:!0},{text:"1 مايو.",correct:!1},{text:"1 يناير.",correct:!1}],explanation:"حدّدت المنظمة الدولية للحماية المدنية 1 مارس يومًا عالميًا، وقد دخل دستورها حيّز التنفيذ في 1 مارس 1972."},{question:"في إقليم كوردستان، لأيّ وزارة يتبع الدفاع المدني؟",options:[{text:"وزارة الداخلية.",correct:!0},{text:"وزارة التربية.",correct:!1},{text:"وزارة التجارة.",correct:!1}],explanation:"يتبع الدفاع المدني وزارة الداخلية، ولكل محافظة مديرية."}]},{id:2,code:"HIS-ORI-102",icon:"Flame",accent:"#c2410c",title:"الحماية المبكرة للمدن: حراسة الحرائق والإطفاء القديم والإغاثة في الكوارث",subtitle:"كيف تعلّم الناس أن الحماية تحتاج إلى تنظيم وقانون وتعاون",summary:"قبل وجود الأجهزة الحديثة كان سكان المدن يواجهون الحرائق والكوارث بأنفسهم: حراسة ليلية وإنذار وإطفاء بالتعاون. ثم أظهرت الحرائق الكبرى أن ذلك لا يكفي، فنشأت قوانين البناء ومنظمات الإغاثة. يعرض هذا الدرس جذور الدفاع المدني.",facts:[{label:"1666",value:"حريق لندن الكبير يلتهم جزءًا كبيرًا من المدينة."},{label:"1667",value:"قانون إعادة بناء لندن يشترط البناء بالطوب أو الحجر."},{label:"1863",value:"اللجنة الدولية للصليب الأحمر تجتمع لأول مرة."},{label:"1864",value:"اعتماد أول اتفاقية جنيف."}],blocks:[{heading:"الحراسة والإنذار",body:"في كثير من المدن القديمة كانت البيوت من الخشب والمواد القابلة للاشتعال ومتلاصقة، فكان حريق صغير قادرًا على إحراق حيّ كامل في ليلة واحدة. لذلك عيّن الناس حرّاسًا ليليين يجوبون الأزقة ليكتشفوا الحريق مبكرًا، وعند رؤيته يُطلَق الإنذار بالصوت العالي أو الأجراس أو وسائل أخرى لإيقاظ الناس. وما زالت هذه الفكرة — اكتشاف الخطر مبكرًا وإنذار الناس مبكرًا — أساس عمل الدفاع المدني اليوم: فأجهزة كشف الدخان والإنذار العام تحقق الهدف نفسه."},{heading:"الإطفاء بالتعاون",body:"قبل المعدات الحديثة كان الناس يطفئون النار بماء يُنقَل يدويًا، فتنتقل الدلاء من يد إلى يد. وكان هذا العمل يحتاج إلى عدد كبير من الناس وتنظيم وأوامر واضحة. ثم صُنعت مضخات الماء اليدوية وظهرت فرق إطفاء منظَّمة. وكان درس هذه المرحلة: التعاون وحده لا يكفي ما لم يصحبه تنظيم وتدريب ومعدات. واليوم أيضًا تعمل فرق الدفاع المدني بالتدريب والمعدات وقيادة واضحة؛ فكل عضو في الفريق يعرف مهمته ومن يصدر الأوامر وكيف يتواصل مع زملائه، وهو ما لم تستطع سلسلة الدلاء القديمة تحقيقه تمامًا."},{heading:"حريق لندن الكبير (1666)",body:"في عام 1666 التهم حريق كبير جزءًا كبيرًا من مدينة لندن. وبعده أصدر البرلمان البريطاني قانونًا لإعادة بناء المدينة يشترط أن تُبنى المباني الجديدة بالطوب أو الحجر وأن يُحدَّد عدد طوابقها. وهذا مثال مهم: أصبحت الكارثة سببًا لقانون يقلل خطر الحريق من أساسه. وبعد الحريق ظهر في لندن أيضًا التأمين ضد الحريق. والدرس لليوم: الحماية ليست إطفاء النار فقط، بل البناء الآمن وقوانين الوقاية أيضًا."},{heading:"الإغاثة في الكوارث والحروب",body:"في عام 1863 اجتمعت في جنيف لأول مرة لجنة أصبحت لاحقًا اللجنة الدولية للصليب الأحمر، وكان أحد مؤسسيها قد ألّف كتابًا عن معاناة الجرحى في ساحة المعركة. وفي عام 1864 أقنعت هذه اللجنة الحكومات باعتماد أول اتفاقية جنيف لحماية الجرحى ومن يسعفونهم. وكانت تلك بداية فكرة كبرى: من يقدّم العون الإنساني يجب أن يُحمى. ووصلت هذه الفكرة لاحقًا، عام 1977، إلى الدفاع المدني أيضًا (الدرس 6)."},{heading:"دروس هذه المرحلة لليوم",body:`• اكتشف الخطر مبكرًا وأنذر الناس مبكرًا: جهاز كشف الدخان في البيت يؤدي هذه المهمة.
• التعاون يحتاج إلى تنظيم: في الطوارئ اتبع تعليمات فرق الدفاع المدني.
• البناء الآمن يحمي الأرواح: أبقِ طريق الخروج مفتوحًا ولا تضع المواد القابلة للاشتعال قرب النار.
• الكوارث دروس: بعد كل حادث اسأل ما الذي يمكن تحسينه.
• العون الإنساني يجب أن يُحمى ويُحترم.
• عند الحريق لست أنت فريق الإطفاء: اخرج وأنذر الناس واتصل بالرقم 115.`}],warnings:["لا تحاول إطفاء حريق كبير بالدلاء أو بنفسك: ذلك زمن مضى؛ اخرج واتصل بالرقم 115.","لا تسدّ طرق الخروج ولا مداخل سيارات الإطفاء: فهي تنقذ الأرواح."],tips:["ركّب جهاز كشف الدخان في البيت واختبره بانتظام.","ضع مع أسرتك خطة خروج من البيت وتدرّبوا عليها.","عند قراءة التاريخ، ابحث عن القانون الذي وُضع بعد كارثة ما."],activity:{prompt:"يطلب المعلم ترتيب هذه الأحداث زمنيًا: أول اتفاقية جنيف، حريق لندن الكبير، أول اجتماع للجنة الصليب الأحمر. أيّ ترتيب صحيح؟",options:[{text:"حريق لندن، ثم لجنة الصليب الأحمر، ثم اتفاقية جنيف.",correct:!0,feedback:"صحيح: 1666 ثم 1863 ثم 1864."},{text:"اتفاقية جنيف، ثم حريق لندن، ثم لجنة الصليب الأحمر.",correct:!1,feedback:"لا: حريق لندن كان عام 1666، قبل اتفاقية 1864 بكثير."},{text:"لجنة الصليب الأحمر، ثم اتفاقية جنيف، ثم حريق لندن.",correct:!1,feedback:"لا: اللجنة والاتفاقية في القرن التاسع عشر، بعد حريق 1666."},{text:"وقعت الثلاثة في السنة نفسها.",correct:!1,feedback:"لا: تفصل بينها قرون: 1666 و1863 و1864."}]},caseStudy:[{prompt:"في حيّ قديم بيوته متلاصقة وأزقته ضيقة، تُشمّ ليلًا رائحة دخان من أحد البيوت. ما أول ما يجب فعله بحسب دروس التاريخ؟",options:[{text:"أنذر الناس بصوت عالٍ واتصل بالرقم 115 من مكان آمن.",correct:!0,feedback:"صحيح: الإنذار المبكر وطلب الفريق المدرَّب هما الدرس الرئيسي من التاريخ."},{text:"ابقَ صامتًا كي لا يخاف الناس.",correct:!1,feedback:"الصمت يضيّع وقتًا ثمينًا؛ والإنذار ينقذ الناس."},{text:"ادخل وحدك لإطفاء النار بالماء.",correct:!1,feedback:"دخول الدخان يعرّض حياتك للخطر؛ هذا عمل الفريق المدرَّب."}]},{prompt:"وصل الفريق وأُطفئ الحريق. وبعد الحادث يسأل مجلس الحيّ عمّا يجب تغييره. أيّ اقتراح يطبّق درس 1666؟",options:[{text:"طلب مشورة الدفاع المدني بشأن البناء الآمن وفتح طرق الخروج.",correct:!0,feedback:"صحيح: بعد 1666 أصبح البناء الآمن أساس الحماية."},{text:"عدم تغيير شيء لأن النار أُطفئت.",correct:!1,feedback:"إذا لم يتغير شيء بقي الخطر نفسه."},{text:"جمع الدلاء في كل زقاق بوصفها الخطة الوحيدة.",correct:!1,feedback:"هذه طريقة قديمة؛ اليوم يحمي الأرواح البناءُ الآمن والفرق المدرَّبة."}]}],quiz:[{question:"لماذا كانت الحرائق تنتشر بسرعة في المدن القديمة؟",options:[{text:"لأن البيوت خشبية ومتلاصقة.",correct:!0},{text:"لأن البيوت حجرية ومتباعدة.",correct:!1},{text:"لأن المدن قريبة من الأنهار.",correct:!1}],explanation:"المواد القابلة للاشتعال وتلاصق البيوت نقلا النار بسرعة من بيت إلى آخر."},{question:"بعد حريق 1666، ماذا اشترط قانون إعادة بناء لندن؟",options:[{text:"البناء بالطوب أو الحجر.",correct:!0},{text:"البناء بالخشب فقط.",correct:!1},{text:"بناء بيوت بطوابق أكثر.",correct:!1}],explanation:"اشترط القانون البناء بالطوب أو الحجر وتحديد الطوابق لتقليل خطر الحريق."},{question:"أيّ درس من حريق لندن صحيح لليوم؟",options:[{text:"الوقاية تبدأ بالبناء الآمن والقوانين.",correct:!0},{text:"الإطفاء هو الطريق الوحيد للحماية.",correct:!1},{text:"الكوارث لا تعلّم شيئًا.",correct:!1}],explanation:"أدى حريق 1666 إلى قانون قلّل الخطر من أساسه، وهذه هي الوقاية."},{question:"ما العمل الذي كان يؤديه الحراس الليليون في المدن القديمة ويؤديه اليوم جهاز كشف الدخان؟",options:[{text:"اكتشاف الحريق مبكرًا وإنذار الناس.",correct:!0},{text:"إطفاء الحريق بأنفسهم بالماء.",correct:!1},{text:"بناء بيوت جديدة بعد الحريق.",correct:!1}],explanation:"هدفهما واحد: اكتشاف الخطر مبكرًا وإنذار الناس مبكرًا."},{question:"أرست اتفاقية جنيف الأولى (1864) فكرة مهمة. ما هي؟",options:[{text:"يجب حماية الجرحى ومن يسعفونهم.",correct:!0},{text:"لكل دولة أن تعامل الجرحى كما تشاء.",correct:!1},{text:"العون الإنساني ممنوع وقت الحرب.",correct:!1}],explanation:"تقول اللجنة الدولية إنها أقنعت الحكومات عام 1864 باعتماد الاتفاقية الأولى لحماية الجرحى ومسعفيهم."},{question:"شبّ حريق كبير في حيّك. أيّ عمل يطبّق درس التاريخ تطبيقًا صحيحًا؟",options:[{text:"الخروج وإنذار الناس والاتصال بالرقم 115.",correct:!0},{text:"تنظيم سلسلة دلاء مع الجيران.",correct:!1},{text:"الوقوف قرب الحريق للتصوير.",correct:!1}],explanation:"اليوم توجد فرق مدرَّبة ومعدات؛ ودور الناس الخروج والإنذار والاتصال بالرقم 115."}]},{id:3,code:"HIS-WWO-103",icon:"CloudLightning",accent:"#64748b",title:"الحرب العالمية الأولى وولادة الحماية من الغارات الجوية",subtitle:"حين أصبحت السماء خطرًا على المدنيين في بيوتهم",summary:"في الحرب العالمية الأولى (1914–1918) قُصفت من الجو، لأول مرة على نطاق واسع، مدنٌ بعيدة عن جبهات القتال، فأصبح المدنيون هدفًا. وأظهر ذلك أن حماية السكان تحتاج إلى إنذار وملاجئ وخطة تُعَدّ قبل الحرب. يبيّن هذا الدرس كيف زرعت هذه التجربة بذرة الدفاع المدني الحديث.",facts:[{label:"1914",value:"اندلاع الحرب العالمية الأولى."},{label:"يناير 1915",value:"أول غارة بالمناطيد (زيبلين) على بريطانيا."},{label:"31 مايو 1915",value:"أول غارة جوية على لندن."},{label:"1918",value:"نهاية الحرب؛ وصارت دروسها أساسًا لتخطيط حماية المدنيين."},{label:"1937",value:"بريطانيا تصدر قانون احتياطات الغارات الجوية (ARP)."}],blocks:[{heading:"حرب من نوع جديد",body:"قبل الحرب العالمية الأولى كانت الحرب تدور غالبًا في ساحات القتال، وكان سكان المدن البعيدة أقل تعرضًا للهجوم المباشر. وفي هذه الحرب ألقت المناطيد الكبيرة المعروفة باسم «زيبلين»، ثم الطائرات، القنابلَ على المدن. وكان ذلك تحولًا كبيرًا: فالبيوت والمدارس والمعامل البعيدة عن الجبهة أصبحت في دائرة الخطر. ولم يكن المدنيون يعرفون كيف يحمون أنفسهم، إذ لم يكن هناك إنذار أو ملاجئ أو تدريب مسبق."},{heading:"الغارات الجوية على بريطانيا",body:"بحسب الأرشيف الوطني البريطاني، كانت أول غارة بالمناطيد على بريطانيا في يناير 1915 على مدن ساحلية، وأول غارة على لندن في 31 مايو 1915. كان الناس يسمعون ليلًا صوت المحركات والانفجارات دون أن يعرفوا ما يجري. واستمرت هذه الغارات طوال الحرب، وقُتل فيها وجُرح كثير من المدنيين. وتعلّمت الحكومة أنه يجب تنظيم وسائل الإنذار وتقليل الأضواء ليلًا وأماكن الاحتماء."},{heading:"أولى إجراءات الحماية",body:`كانت الإجراءات الأولى بسيطة، لكنها كانت أساس كل ما جاء بعدها:
• الإنذار: محاولة إعلام الناس بالخطر قبل وصول الغارة.
• تقليل الأضواء: كانت أضواء المدينة تُخفَّف ليلًا كي لا تُرى بسهولة من الجو.
• الاحتماء: لجأ الناس إلى أماكن محمية تحت الأرض أو داخل مبانٍ متينة.
• العون بعد الغارة: إطفاء الحرائق وإخراج العالقين تحت المباني وإسعاف الجرحى.`},{heading:"الحرائق والإنقاذ بعد الغارة",body:"لم تكن القنابل الجوية تُحدث الضرر بالانفجار وحده، بل كثيرًا ما أشعلت الحرائق وأسقطت المباني. وأظهر ذلك أن فرق الإطفاء والإنقاذ والإسعاف يجب أن تعمل معًا وبخطة واحدة. وتبيّن أيضًا أن لسكان الحيّ دورًا: إنذار الجيران، ودلالة الفريق على مكان الحادث، وإبعاد الناس عن المباني الخطرة. وأصبح هذا العمل المشترك بين الفرق والسكان لاحقًا من أسس الدفاع المدني."},{heading:"من التجربة إلى التخطيط",body:"بعد الحرب أدركت الحكومات أن حماية السكان لا يجوز أن تبدأ وقت الغارة، بل يجب التخطيط لها قبل الحرب: من يُطلق الإنذار، وأين الملاجئ، ومن يطفئ الحرائق، ومن ينقذ الجرحى. وفي بريطانيا نما هذا التفكير في السنوات بين الحربين، وصدر عام 1937 قانون احتياطات الغارات الجوية (Air Raid Precautions) الذي حمّل السلطات المحلية مسؤولية إعداد الحماية. وكانت هذه من أهم الخطوات نحو دفاع مدني منظَّم."},{heading:"دروس هذه الحرب لليوم",body:`• الإنذار المبكر ينقذ الأرواح: استمع اليوم أيضًا إلى الإنذارات الرسمية.
• يجب أن تكون الخطة قبل الكارثة لا أثناءها.
• على كل بيت أن يعرف أقرب مكان آمن.
• العون بعد الغارة أو الكارثة يحتاج إلى فرق مدرَّبة: اتصل بالرقم 115 وأبقِ الطريق مفتوحًا لها.
• للأجهزة المحلية دور رئيسي في الحماية، مثل مديرية الدفاع المدني في المحافظة.
• اتبع تعليمات الدفاع المدني والجهة المختصة.`}],warnings:["عند صدور إنذار رسمي لا تبقَ في الخارج للمشاهدة أو التصوير: توجّه فورًا إلى مكان آمن.","لا تقترب من الأجسام غير المنفجرة أو بقايا القنابل ولا تلمسها: ابتعد وأبعد الناس واتصل بالرقم 115."],tips:["حدّد مع أسرتك أقرب مكان آمن إلى البيت.","خذ المعلومات من المصادر الرسمية فقط لا من الإشاعات.","جهّز حقيبة طوارئ فيها ماء ومصباح وأدويتك."],activity:{prompt:"في عام 1915 هوجمت مدينة من الجو ليلًا ولم يعرف الناس ماذا يفعلون. لو كنت في مجلس تلك المدينة، فما أول اقتراح تقدّمه للحماية؟",options:[{text:"وسيلة لإنذار الناس وتحديد أماكن الاحتماء قبل الغارة.",correct:!0,feedback:"صحيح: الإنذار والملاجئ أول دروس هذه الحرب."},{text:"الانتظار حتى الغارة التالية ثم اتخاذ القرار.",correct:!1,feedback:"الانتظار يعرّض الأرواح للخطر؛ يجب أن تسبق الخطةُ الغارة."},{text:"زيادة أضواء المدينة ليلًا.",correct:!1,feedback:"هذا يجعل المدينة أوضح من الجو؛ وكان الإجراء تقليل الأضواء."},{text:"الطلب من الناس البقاء في الخارج لمشاهدة الغارة.",correct:!1,feedback:"البقاء في الخارج يزيد خطر الإصابة؛ الاحتماء ضروري."}]},caseStudy:[{prompt:"اليوم، أثناء تمرين في المدرسة، يدوّي صوت الإنذار، فيضحك بعض الطلاب ويقولون: «إنه مجرد تمرين». بحسب درس 1915، ماذا تفعل؟",options:[{text:"أتوجه بهدوء وفق الخطة إلى المكان الآمن وأشجّع زملائي.",correct:!0,feedback:"صحيح: التمرين يحوّل دروس التاريخ إلى عمل؛ وفي الحقيقة ستستجيب بسرعة."},{text:"أبقى في مكاني لأن هذا ليس حقيقيًا.",correct:!1,feedback:"في 1915 لم يعرف الناس ماذا يفعلون؛ والتمرين يعالج هذا النقص."},{text:"أخرج لأرى ما يحدث.",correct:!1,feedback:"الخروج للمشاهدة يبعدك عن المكان الآمن."}]},{prompt:"بعد التمرين يسأل المدير عن النواقص. أيّ اقتراح يطبّق فعلًا درس التخطيط قبل الكارثة؟",options:[{text:"كتابة خطة واضحة بمسؤولين وأماكن آمنة وتمارين دورية.",correct:!0,feedback:"صحيح: هذا هو درس ما بعد الحرب الأولى الذي صار أساس ARP."},{text:"إيقاف التمارين لأن الطلاب يضحكون.",correct:!1,feedback:"دون تمارين لن يعرف الناس ماذا يفعلون عند الخطر الحقيقي."},{text:"ترك كل طالب يقرر بنفسه.",correct:!1,feedback:"دون خطة يذهب كل واحد في اتجاه وتعمّ الفوضى."}]}],quiz:[{question:"ما الجديد في الحرب العالمية الأولى الذي عرّض المدنيين للخطر؟",options:[{text:"قصف المدن من الجو.",correct:!0},{text:"حرائق الأجهزة الكهربائية.",correct:!1},{text:"فيضانات الأنهار في الربيع.",correct:!1}],explanation:"ألقت المناطيد والطائرات القنابل على مدن بعيدة عن الجبهة."},{question:"بحسب الأرشيف الوطني البريطاني، متى كانت أول غارة على لندن؟",options:[{text:"31 مايو 1915.",correct:!0},{text:"1 سبتمبر 1939.",correct:!1},{text:"12 أغسطس 1949.",correct:!1}],explanation:"أول غارة على لندن كانت في 31 مايو 1915؛ أما التاريخان الآخران فللحرب الثانية واتفاقيات جنيف."},{question:"لماذا كانت أضواء المدينة تُخفَّف ليلًا؟",options:[{text:"كي لا تُرى المدينة بسهولة من الجو.",correct:!0},{text:"لتوفير الكهرباء للمعامل.",correct:!1},{text:"لينام الناس مبكرًا ولا يبقوا في الخارج.",correct:!1}],explanation:"تقليل الأضواء يصعّب رؤية المدينة من الجو ليلًا."},{question:"ما الدرس الرئيسي الذي تعلّمته الحكومات بعد الحرب الأولى؟",options:[{text:"يجب التخطيط لحماية السكان قبل الحرب.",correct:!0},{text:"الغارات الجوية لن تتكرر في أي حرب قادمة.",correct:!1},{text:"حماية السكان من عمل الجيش وحده دون غيره.",correct:!1}],explanation:"أدى هذا الدرس إلى تخطيط ARP في بريطانيا وقانون 1937."},{question:"لمن أسند قانون ARP لعام 1937 في بريطانيا مهمة إعداد الحماية؟",options:[{text:"السلطات المحلية.",correct:!0},{text:"الشركات الخاصة.",correct:!1},{text:"كل بيت وحده.",correct:!1}],explanation:"حمّل القانون السلطات المحلية مسؤولية إعداد احتياطات الغارات الجوية."},{question:"عُثر في حيّك على قطعة معدنية مجهولة قد تكون ذخيرة. ماذا تفعل؟",options:[{text:"أبتعد وأُبعد الناس وأتصل بالرقم 115.",correct:!0},{text:"أحملها إلى مركز الشرطة.",correct:!1},{text:"أقترب لألتقط صورة وأنشرها.",correct:!1}],explanation:"قد تنفجر الأجسام غير المنفجرة عند لمسها؛ لا تلمسها وابتعد واتصل بالرقم 115."}]},{id:4,code:"HIS-WWT-104",icon:"Users",accent:"#475569",title:"الحرب العالمية الثانية: الملاجئ والتعتيم والمراقبون والمتطوعون",subtitle:"حين أصبح المجتمع كله جزءًا من حماية نفسه",summary:"في الحرب العالمية الثانية (1939–1945) أصبحت الغارات الجوية على المدن أكبر بكثير، فطبّقت الدول الخطط التي أعدّتها بعد الحرب الأولى: الملاجئ والتعتيم ليلًا ومراقبو الأحياء وآلاف المتطوعين. يبيّن هذا الدرس كيف عمل هذا التنظيم وما الدروس التي بقيت للدفاع المدني اليوم.",facts:[{label:"1937",value:"قانون ARP في بريطانيا؛ وبدء إعداد المراقبين والمتطوعين."},{label:"1 سبتمبر 1939",value:"بدء التعتيم في بريطانيا وتولّي المراقبين تطبيقه."},{label:"1939–1945",value:"الحرب العالمية الثانية وغارات جوية كبيرة على المدن."},{label:"1949",value:"اتفاقيات جنيف الجديدة، ومنها الاتفاقية الرابعة لحماية المدنيين."}],blocks:[{heading:"الاستعداد قبل الحرب",body:"كان درس الحرب الأولى أن الحماية يجب أن تُعَدّ قبل الحرب. لذلك أصدرت بريطانيا عام 1937 قانون احتياطات الغارات الجوية (ARP)، وبدأت السلطات المحلية الاستعداد. وكان الهدف أن يكون لكل حيّ مراقبون وأماكن احتماء وفرق إطفاء وإسعاف أولي، وأن يتعلم الناس ما يفعلونه عند الإنذار. وهكذا أصبح الدفاع المدني عملًا منظَّمًا يشمل المجتمع كله، لا عمل جهاز واحد فقط."},{heading:"مراقبو الأحياء (ARP wardens)",body:`كان مراقبو ARP من أهل الحيّ نفسه، رجالًا ونساءً، وكثير منهم متطوعون، يعرفون سكان حيّهم ويعرفون من يسكن أين. ومن مهامهم:
• التجوال ليلًا في الأزقة للتأكد من عدم ظهور أي ضوء إلى الخارج.
• إنذار الناس وإرشادهم إلى الملاجئ.
• الإبلاغ عن أماكن سقوط القنابل والحرائق للفرق المعنية.
• نصح الناس ومساعدتهم بعد الغارة.
ويقترب هذا الدور اليوم من دور متطوعي الأحياء الذين يعملون مع الدفاع المدني.`},{heading:"التعتيم (Blackout)",body:"منذ 1 سبتمبر 1939 فُرض التعتيم في بريطانيا: كانت النوافذ تُغطّى بستائر داكنة، وتُخفَّف أضواء الشوارع أو تُطفأ كي لا تُرى المدينة من الجو ليلًا، وكان المراقبون يتأكدون من تطبيق هذه التعليمات. لكن للتعتيم مخاطره أيضًا، إذ ازدادت حوادث الطرق في الشوارع المظلمة. وهذا درس مهم: كل إجراء وقائي يجب أن يُطبَّق بوعي، مع الانتباه إلى المخاطر الجديدة التي قد تنشأ عنه."},{heading:"الملاجئ",body:"احتمى الناس بطرق عدة: فبعض الملاجئ الصغيرة كانت تُنصب في حدائق البيوت، وبعضها ملاجئ عامة تتسع لكثيرين، وفي بعض المدن لجأ الناس إلى أماكن تحت الأرض. وأهم درس أن الملاجئ يجب أن تكون جاهزة قبل الخطر، وأن يعرف الناس مواقعها وكيف يصلون إليها بسرعة وهدوء، وأن يتوفر فيها الماء والإضاءة والإسعافات الأولية. واليوم أيضًا تحدد خطط الطوارئ الأماكن الآمنة ونقاط التجمع."},{heading:"الفرق والمتطوعون معًا",body:"ضمن تنظيم ARP عملت أنواع عدة من الخدمات معًا: المراقبون، وفرق الإطفاء، وفرق الإنقاذ التي تُخرج الناس من تحت المباني المنهارة، وفرق الإسعافات الأولية والإسعاف. وكان كثير من هؤلاء متطوعين، فصارت الحماية مسؤولية الجميع. وما زالت هذه الفكرة — أن تعمل الفرق المحترفة والمتطوعون المدرَّبون معًا — أساسًا في الدفاع المدني اليوم: يعمل منتسبو الدفاع المدني ويساعدهم الناس المدرَّبون، لا أن يحلّوا محلهم."},{heading:"بعد الحرب",body:"قتلت الحرب الثانية أعدادًا كبيرة من المدنيين ودمّرت المدن. وفي عام 1949 اعتُمدت اتفاقيات جنيف الجديدة، والاتفاقية الرابعة منها مخصصة لحماية المدنيين وقت الحرب. وفي السنوات التالية أصبحت تجربة ARP أساس أجهزة الدفاع المدني في دول كثيرة، ثم في عام 1977 حظيت مهام الدفاع المدني نفسها بالحماية في القانون الدولي (الدرس 6)."}],warnings:["عند الإنذار الرسمي توجّه بهدوء إلى المكان الآمن؛ لا تركض ولا تسدّ الطريق على الآخرين.","لا يدخل المتطوع وحده مبنًى منهارًا: الإنقاذ عمل الفريق المدرَّب."],tips:["اعرف المكان الآمن ونقطة التجمع في البيت والمدرسة والعمل.","إن أردت التطوع فاسأل مديرية الدفاع المدني عن كيفية التدريب.","تعرّف إلى جيرانك، خاصة كبار السن وذوي الاحتياجات الخاصة، لتساعدهم في الطوارئ."],activity:{prompt:"أنت متطوع في حيّك مثل مراقبي ARP. بعد حادث رأيت مبنًى منهارًا وسمعت صوت شخص من تحته. ما العمل الصحيح؟",options:[{text:"أتصل بالرقم 115 وأعطي الموقع الدقيق وأُبعد الناس وأرشد الفريق.",correct:!0,feedback:"صحيح: هذا عمل المراقب: الإبلاغ وإبعاد الناس وإرشاد الفريق."},{text:"أدخل وحدي بين الأنقاض لإخراج الشخص.",correct:!1,feedback:"قد ينهار المبنى مجددًا؛ الإنقاذ عمل الفريق المدرَّب."},{text:"أصوّر المشهد لأنشره على مواقع التواصل.",correct:!1,feedback:"التصوير لا يساعد ويضيّع وقتًا ثمينًا؛ اتصل بالرقم 115 أولًا."},{text:"أعود إلى البيت وأنتظر أن يبلّغ غيري.",correct:!1,feedback:"الانتظار يضيّع وقت الإنقاذ؛ المراقب يبلّغ فورًا."}]},caseStudy:[{prompt:"تريد مدينة تخفيف الأضواء ليلًا كي لا تُرى من الجو، كتعتيم 1939، وأنت عضو في لجنة السلامة. ما أول خطر جديد يجب الانتباه إليه؟",options:[{text:"ازدياد حوادث الطرق وسقوط المارّة في الشوارع المظلمة.",correct:!0,feedback:"صحيح: تعتيم 1939 زاد حوادث الطرق؛ وكل إجراء يجلب مخاطر جديدة."},{text:"لا خطر جديد، فالتعتيم يحل كل شيء.",correct:!1,feedback:"كل إجراء وقائي قد يخلق مخاطر جديدة يجب رصدها."},{text:"لن تخرج روائح الطعام من البيوت.",correct:!1,feedback:"هذا ليس خطرًا على السلامة؛ الخطر الحقيقي كان حوادث الطرق."}]},{prompt:"تسأل اللجنة كيف تقلل هذا الخطر الجديد دون أن تفقد الحماية. أيّ قرار أفضل؟",options:[{text:"توعية الناس وتخفيف سرعة السيارات وتدريب المراقبين على الإرشاد.",correct:!0,feedback:"صحيح: التوعية والتنظيم يقللان المخاطر الجديدة مع بقاء الحماية."},{text:"إلغاء التعتيم كليًا.",correct:!1,feedback:"هذا يُفقد الحماية الأساسية؛ الحل في التنظيم لا الإلغاء."},{text:"عدم فعل شيء وانتظار ما يحدث.",correct:!1,feedback:"عدم الفعل سيزيد الحوادث؛ يجب تقليل الخطر بخطة."}]}],quiz:[{question:"كان مراقبو ARP يجوبون الأزقة ليلًا. ما إحدى مهامهم الرئيسية؟",options:[{text:"التأكد من عدم ظهور أي ضوء إلى الخارج.",correct:!0},{text:"بيع الطعام لسكان الحيّ.",correct:!1},{text:"قتال قوات العدو في الشوارع.",correct:!1}],explanation:"كان المراقبون يتأكدون من تطبيق التعتيم، وينذرون الناس، ويبلّغون عن الحوادث."},{question:"متى بدأ التعتيم في بريطانيا؟",options:[{text:"1 سبتمبر 1939.",correct:!0},{text:"31 مايو 1915.",correct:!1},{text:"1 مارس 1972.",correct:!1}],explanation:"فُرض التعتيم منذ 1 سبتمبر 1939؛ أما 1915 فأول غارة على لندن، و1972 دستور ICDO."},{question:"أيّ درس من ملاجئ الحرب الثانية صحيح لليوم؟",options:[{text:"يجب تحديد المكان الآمن ومعرفته قبل الخطر.",correct:!0},{text:"يُعثر على المكان الآمن بسرعة وقت الخطر.",correct:!1},{text:"الملاجئ لكبار السن فقط.",correct:!1}],explanation:"الاستعداد المسبق ومعرفة المكان يتيحان الوصول إليه بسرعة وهدوء."},{question:"أثناء حادث، ما دور المتطوع المدرَّب مع فرق الدفاع المدني؟",options:[{text:"يساعد الفريق ولا يحلّ محله.",correct:!0},{text:"يأمر الفريق ويتولى القيادة.",correct:!1},{text:"يدخل وحده الأماكن الخطرة.",correct:!1}],explanation:"على نموذج ARP يبلّغ المتطوع ويرشد الناس ويتبع تعليمات الفريق."},{question:"أيّ اتفاقية من اتفاقيات جنيف (1949) مخصصة لحماية المدنيين وقت الحرب؟",options:[{text:"الاتفاقية الرابعة.",correct:!0},{text:"الاتفاقية الأولى.",correct:!1},{text:"الاتفاقية الثانية.",correct:!1}],explanation:"تحمي اتفاقية جنيف الرابعة (1949) المدنيين وقت الحرب."},{question:"تجمّع الناس حول مبنى منهار بعد غارة. بصفتك مراقب ARP، ما أول ما تفعله؟",options:[{text:"إبعاد الناس والإبلاغ عن الموقع لفريق الإنقاذ.",correct:!0},{text:"الطلب من الناس رفع الأنقاض بأيديهم.",correct:!1},{text:"ترك الناس في المكان ليروا ما حدث.",correct:!1}],explanation:"قد تنهار الأنقاض مجددًا؛ إبعاد الناس والإبلاغ السريع يحميان الأرواح ويفتحان الطريق للفريق."}]},{id:5,code:"HIS-CWR-105",icon:"Siren",accent:"#0f766e",title:"الحرب الباردة: صفارات الإنذار والملاجئ وتخطيط الدفاع المدني",subtitle:"من الخوف من حرب كبرى إلى الاستعداد لجميع الكوارث",summary:"بعد الحرب العالمية الثانية بدأت الحرب الباردة، وساد الخوف من حرب كبرى بالأسلحة النووية. فأنشأت دول كثيرة أجهزة دفاع مدني دائمة: صفارات إنذار وخطط إخلاء وملاجئ ومتطوعين مدرَّبين. ثم اتجهت هذه الأجهزة إلى الاستعداد لجميع أنواع الكوارث. يشرح هذا الدرس هذا التحول.",facts:[{label:"1949",value:"تأسيس فيلق الدفاع المدني (Civil Defence Corps) من المتطوعين في بريطانيا."},{label:"1958",value:"المنظمة الدولية للحماية المدنية تتخذ اسم ICDO."},{label:"1968",value:"حلّ فيلق الدفاع المدني في بريطانيا."},{label:"1972",value:"أصبحت ICDO منظمة حكومية دولية بدخول دستورها حيّز التنفيذ في 1 مارس."},{label:"1979",value:"تأسيس FEMA في الولايات المتحدة بمهمتين: إدارة الطوارئ والدفاع المدني."}],blocks:[{heading:"خوف جديد",body:"الحرب الباردة هي المرحلة التي بدأت بعد الحرب العالمية الثانية، حين ساد تنافس طويل بين الدول الكبرى دون حرب مباشرة كبرى بينها. وأوجدت الأسلحة النووية خوفًا جديدًا: فهجوم واحد قد يدمّر مدينة كاملة في وقت قصير جدًا. لذلك رأت الحكومات أن الدفاع المدني لا يجوز أن يُبنى وقت الحرب فقط، بل يجب أن يكون جهازًا دائمًا له خطط وتدريب ومعدات حتى في زمن السلم."},{heading:"صفارات الإنذار والإنذار العام",body:"في هذه المرحلة نصبت دول كثيرة شبكات صفارات إنذار في المدن لإنذار الناس بسرعة، وكانت التعليمات تُبث عبر الإذاعة، وتعلّم الناس معنى صوت الصفارة وما يفعلونه عند سماعها. وما زالت هذه الأنظمة مهمة اليوم: ففي أماكن كثيرة تُستخدم الصفارات والإذاعة والتلفزيون ورسائل الهاتف للإنذار من الفيضانات والحرائق والمواد الخطرة. أما في دهوك فيجب أن تؤخذ وسائل الإنذار الرسمية ومعنى كل صوت من مديرية الدفاع المدني."},{heading:"الملاجئ وخطط الإخلاء",body:`وضعت الحكومات خططًا كبيرة لحماية السكان:
• تحديد المباني المتينة ملاجئَ ووضع علامات عليها.
• خطط لإخلاء المدن وطرق الخروج.
• تخزين الماء والغذاء ومعدات الإسعافات الأولية.
• تدريب الناس في المدارس والمعامل.
ولم تنجح هذه الخطط كلها، وكثيرًا ما دار حولها جدل، لكنها تركت درسًا مهمًا: الناس المستعدون، الذين يعرفون أين يحتمون وكيف يخرجون، فرصتهم في النجاة أكبر.`},{heading:"المتطوعون والتدريب",body:"في بريطانيا تأسس عام 1949 «فيلق الدفاع المدني»، وهو منظمة متطوعين لإدارة المناطق المتضررة بعد طارئ كبير، وكان أعضاؤه يتدربون على الإنقاذ والإسعافات الأولية والإنذار ومساعدة الناس. وفي عام 1968 حُلّ هذا الفيلق. ويبيّن هذا المثال أن المتطوعين المدرَّبين قد يكونون قوة كبيرة، وأن الدفاع المدني يحتاج إلى دعم مستمر من الحكومة والمجتمع ليبقى."},{heading:"من الحرب إلى جميع الكوارث",body:"مع الوقت رأت الدول أن المعدات والتدريب نفسها — الصفارات والخطط وفرق الإنقاذ والملاجئ — لازمة أيضًا للفيضانات والزلازل والحرائق الكبرى والحوادث الكيميائية. فمثلًا أُنشئت FEMA في الولايات المتحدة عام 1979 وأُسندت إليها مهمتان معًا: إدارة الطوارئ والدفاع المدني. وأصبحت ICDO منظمة حكومية دولية عام 1972. واليوم يعمل الدفاع المدني في إقليم كوردستان أيضًا في مواجهة جميع أنواع المخاطر."},{heading:"دروس الحرب الباردة لليوم",body:`• يجب أن يكون الاستعداد دائمًا، لا حين يقترب الخطر فقط.
• لا ينفع الإنذار إلا إذا عرف الناس معناه وما يفعلون.
• خطة البيت: جهّز المكان الآمن ونقطة التجمع وحقيبة الطوارئ.
• التمارين الدورية في المدارس والمعامل تحوّل الخطة إلى عمل.
• المتطوعون المدرَّبون قوة كبيرة، لكنهم يعملون وفق تعليمات الدفاع المدني.
• يجب تحديث الخطط القديمة دوريًا لتشمل المخاطر الجديدة.
• خذ المعلومات من المصادر الرسمية فقط ولا تنشر الإشاعات.`}],warnings:["عند صدور إنذار رسمي لا تتجاهله ولا تنتظر تأكيدًا من مواقع التواصل: اتبع التعليمات.","لا تنشر إنذارات كاذبة أو إشاعات مخيفة: فهي تربك الناس وتصعّب عمل الفرق."],tips:["اسأل مديرية الدفاع المدني عن وسائل الإنذار الرسمية في منطقتك.","احتفظ في البيت بمذياع يعمل بالبطاريات ومصباح لانقطاع الكهرباء.","حدّد مع أسرتك خطة إخلاء ومكان تجمّع خارج البيت."],activity:{prompt:"تسمع في حيّك صفارة إنذار لا تعرف معناها. ما التصرف الصحيح؟",options:[{text:"أدخل وأتابع الإذاعة أو المصادر الرسمية وأتبع تعليمات الدفاع المدني.",correct:!0,feedback:"صحيح: الصفارة للتنبيه، والتعليمات الرسمية تقول لك ما تفعل."},{text:"أصعد إلى السطح لأرى ما يحدث.",correct:!1,feedback:"هذا يبقيك في الخارج معرّضًا للخطر؛ خذ التعليمات الرسمية أولًا."},{text:"أتجاهلها لأنها قد تكون تمرينًا.",correct:!1,feedback:"التجاهل خطر؛ وحتى لو كان تمرينًا فيجب التعامل معه بجدية."},{text:"أكتب على مواقع التواصل أن كارثة كبرى وقعت.",correct:!1,feedback:"هذا ينشر إشاعات غير مؤكدة ويربك الناس."}]},caseStudy:[{prompt:"لدى مدينة خطط حماية قديمة من زمن الحرب الباردة مخصصة للغارات الجوية فقط، ويسأل عضو في المجلس هل تكفي اليوم. بماذا تجيب؟",options:[{text:"يجب تحديثها لتشمل جميع المخاطر: الفيضانات والزلازل والحرائق والمواد الخطرة.",correct:!0,feedback:"صحيح: هذا هو التحول نفسه الذي نقل الدفاع المدني من الحرب إلى جميع الكوارث."},{text:"نعم، تكفي لأنها مكتوبة.",correct:!1,feedback:"خطة قديمة لا تشمل مخاطر اليوم لا تحمي الناس."},{text:"لا حاجة إلى خطط، فالفرق تقرر وقت الكارثة.",correct:!1,feedback:"درس التاريخ كله: يجب أن تسبق الخطةُ الكارثة."}]},{prompt:"قرّر المجلس تحديث الخطة. أيّ خطوة يجب أن تكون أولًا لتكون الخطة مفيدة للناس؟",options:[{text:"تحديد مخاطر المنطقة ووسائل الإنذار بالتنسيق مع الدفاع المدني والجهة المختصة.",correct:!0,feedback:"صحيح: تبدأ الخطة بمعرفة المخاطر ووسائل الإنذار."},{text:"شراء صفارات جديدة دون خطة أو تدريب.",correct:!1,feedback:"الصفارة دون تدريب لا تحمي؛ يجب أن يعرف الناس معناها."},{text:"إخفاء الخطة عن الناس كي لا يخافوا.",correct:!1,feedback:"خطة لا يعرفها الناس لا تنفع في الطوارئ."}]}],quiz:[{question:"لماذا أصبح الدفاع المدني جهازًا دائمًا في الحرب الباردة؟",options:[{text:"لأن هجومًا واحدًا قد يدمّر مدينة بسرعة فلا يبقى وقت للاستعداد.",correct:!0},{text:"لأن حرائق البيوت توقفت كليًا في تلك المرحلة.",correct:!1},{text:"لأن التطوع كان ممنوعًا بالقانون في تلك المرحلة.",correct:!1}],explanation:"لم تترك الأسلحة النووية وقتًا للاستعداد عند الهجوم، فلزم أن يكون الاستعداد دائمًا."},{question:"أيّ هذه الدروس بقي من خطط الملاجئ والإخلاء في الحرب الباردة؟",options:[{text:"الناس المستعدون الذين يعرفون أين يحتمون فرصتهم في النجاة أكبر.",correct:!0},{text:"الملاجئ تحل كل المشكلات تمامًا ودون تدريب.",correct:!1},{text:"يجب إخفاء خطط الإخلاء عن الناس كي لا يخافوا.",correct:!1}],explanation:"الاستعداد ومعرفة المكان الآمن وطريق الخروج تحمي الأرواح؛ وإخفاء الخطط يفقدها فائدتها."},{question:"متى تأسس فيلق الدفاع المدني في بريطانيا ومتى حُلّ؟",options:[{text:"1949 و1968.",correct:!0},{text:"1915 و1918.",correct:!1},{text:"1972 و1979.",correct:!1}],explanation:"تأسس الفيلق عام 1949 وحُلّ عام 1968؛ أما 1915–1918 فالحرب الأولى، و1972/1979 فـICDO وFEMA."},{question:"ما المهمتان اللتان أُسندتا إلى FEMA معًا عام 1979؟",options:[{text:"إدارة الطوارئ والدفاع المدني.",correct:!0},{text:"حماية الحدود وإدارة الجمارك.",correct:!1},{text:"علاج المرضى وبناء المستشفيات.",correct:!1}],explanation:"بحسب موقع FEMA، أُسندت إليها عام 1979 المهمة المزدوجة: إدارة الطوارئ والدفاع المدني."},{question:"ما الطريقة الصحيحة اليوم لمعرفة معنى الصفارات والإنذارات في منطقتك؟",options:[{text:"سؤال مديرية الدفاع المدني والجهة المختصة.",correct:!0},{text:"تصديق أي رسالة تنتشر على مواقع التواصل الاجتماعي.",correct:!1},{text:"تخمين المعنى بنفسك حسب علوّ الصوت وطوله.",correct:!1}],explanation:"تختلف وسائل الإنذار من مكان لآخر، والمصادر الرسمية وحدها تعطي المعنى الصحيح."},{question:"أيّ عبارة تصف تحوّل الدفاع المدني بعد الحرب الباردة على أفضل وجه؟",options:[{text:"من الحماية من الهجمات الحربية إلى الاستعداد لجميع الكوارث.",correct:!0},{text:"من حماية المدنيين إلى حماية القوات والقواعد العسكرية وحدها.",correct:!1},{text:"من عمل دائم إلى عمل لا يُؤدّى إلا في زمن الحرب.",correct:!1}],explanation:"استُخدمت المعدات والتدريب نفسها للفيضانات والزلازل والحرائق، وFEMA مثال على ذلك."}]},{id:6,code:"HIS-IHL-106",icon:"Scale",accent:"#ea580c",title:"القانون الدولي الإنساني: اتفاقيات جنيف والبروتوكول الإضافي الأول (1977) وحماية الدفاع المدني",subtitle:"لماذا يُحمى منتسبو الدفاع المدني ومبانيه ومعداته وما شارته",summary:"القانون الدولي الإنساني هو القانون الذي يحمي وقت الحرب من لا يشاركون في القتال. وقد منح البروتوكول الإضافي الأول (1977) الدفاعَ المدني حماية خاصة: فالهجوم على منتسبيه ومبانيه ومعداته محظور، ووُضعت له شارة دولية مميزة: مثلث أزرق متساوي الأضلاع على خلفية برتقالية. ويشرح الدرس التالي الشارة الدولية بالتفصيل.",facts:[{label:"1864",value:"اتفاقية جنيف الأولى: حماية الجرحى ومسعفيهم."},{label:"1949",value:"اتفاقيات جنيف الأربع؛ والرابعة تحمي المدنيين."},{label:"1977",value:"البروتوكول الإضافي الأول؛ والمواد 61 إلى 67 مخصصة للدفاع المدني."},{label:"الشارة",value:"مثلث أزرق متساوي الأضلاع على خلفية برتقالية."}],blocks:[{heading:"ما القانون الدولي الإنساني؟",body:"القانون الدولي الإنساني (IHL) مجموعة من القواعد تخفف المعاناة وقت الحرب: فهو يحمي من لا يشاركون في القتال، كالمدنيين والطواقم الطبية وعمال الإغاثة الإنسانية، ويقيّد وسائل القتال وأساليبه. بدأ هذا القانون باتفاقية جنيف الأولى عام 1864، ثم اعتُمدت اتفاقيات جنيف الأربع عام 1949، والبروتوكولان الإضافيان عام 1977. واللجنة الدولية للصليب الأحمر (ICRC) هي حارسة هذا القانون وتعمل على نشره."},{heading:"الدفاع المدني في البروتوكول الأول",body:"تقول اللجنة الدولية إن البروتوكول الإضافي الأول لعام 1977 هو الذي يحدد حماية الدفاع المدني تحديدًا خاصًا، والمواد 61 إلى 67 منه مخصصة للدفاع المدني. ويُعرَّف الدفاع المدني بخمس عشرة مهمة إنسانية، منها: الإنذار والإخلاء والملاجئ والإنقاذ والخدمات الطبية والإسعافات الأولية ومكافحة الحرائق وإزالة آثار الخطر والمساعدة العاجلة في إعادة الخدمات الضرورية. أي إن الأعمال التي تؤديها فرق الدفاع المدني كل يوم يحميها القانون وقت الحرب أيضًا. وتطبَّق هذه القواعد في النزاعات المسلحة الدولية."},{heading:"ما الذي يُحمى؟",body:`بحسب البروتوكول يُحظر الهجوم على:
• منتسبي منظمات الدفاع المدني.
• مبانيها ومراكزها.
• مركباتها ومعداتها ولوازمها.
• الملاجئ المعدّة للمدنيين.
وتتيح هذه الحماية لفرق الدفاع المدني أداء عملها الإنساني حتى لو دار القتال داخل المدينة. لكن الحماية مرتبطة بشرط مهم: أن تقتصر على مهامها الإنسانية وألّا تشارك في القتال.`},{heading:"متى تنتهي الحماية؟",body:"بحسب المادة 65 لا تنتهي الحماية إلا إذا استُخدم المنتسبون أو المباني أو المعدات في أعمال ضارة بالعدو خارج مهامهم الإنسانية، ولا يكون ذلك إلا بعد توجيه إنذار بمهلة معقولة لم يُستجب له. ويبيّن البروتوكول أن أمورًا معينة لا تُعدّ ضارة، مثل حمل المنتسبين أسلحة فردية خفيفة لحفظ النظام أو للدفاع عن النفس. وهذا يبيّن أن القانون يحرص بدقة على صون حماية الفرق الإنسانية."},{heading:"الشارة الدولية للدفاع المدني",body:"حدّدت المادة 66 شارة خاصة ليسهل التعرف على منتسبي الدفاع المدني ومبانيه ومركباته وملاجئه: مثلث أزرق متساوي الأضلاع على خلفية برتقالية، يوضع على الملابس والمركبات والمباني. والشارة للتعريف، كي تعلم جميع الأطراف أن هؤلاء الأشخاص وهذه الأماكن تؤدي عملًا إنسانيًا ولا يجوز مهاجمتها. ويُحمى العسكريون المخصصون للدفاع المدني أيضًا (المادة 67) إذا حملوا الشارة وعملوا على أرض دولتهم ولم يشاركوا في القتال. واستخدام الشارة مقصور على الأشخاص والجهات المأذون لها."},{heading:"ماذا يعني هذا القانون لك؟",body:`• احترم فرق الدفاع المدني ولا تعترض طريقها في السلم والحرب.
• تعرّف إلى شارة المثلث الأزرق على الخلفية البرتقالية واحترمها.
• لا تضع الشارة على ملابسك أو سيارتك أو مبانيك إن لم تكن مأذونًا لك.
• لا تنشر صور الضحايا واحترم كرامتهم.
• إن كان لديك سؤال عن استخدام الشارة فاسأل مديرية الدفاع المدني.
• يبيّن تاريخ هذا المساق أن حماية الناس مسؤولية الجميع: معرفة واستعداد واحترام.`}],warnings:["لا تستخدم شارة الدفاع المدني دون إذن: فإساءة استخدامها تُضعف احترامها وتعرّض حماية الفرق للخطر.","لا يجوز لمنتسبي الدفاع المدني المشاركة في القتال: فحمايتهم مرتبطة بعملهم الإنساني."],tips:["احفظ صورة الشارة الدولية: مثلث أزرق وخلفية برتقالية.","لمزيد من المعلومات عن القانون الإنساني راجع موقع اللجنة الدولية للصليب الأحمر.","شارك دروس هذا المساق مع أسرتك، خاصة درس احترام فرق الطوارئ."],activity:{prompt:"ترى سيارة عليها مثلث أزرق على خلفية برتقالية. ماذا تعني هذه الشارة؟",options:[{text:"إنها مركبة دفاع مدني تحميها أحكام القانون الدولي.",correct:!0,feedback:"صحيح: هذه الشارة الدولية للدفاع المدني وفق المادة 66."},{text:"إنها مركبة عسكرية تشارك في القتال.",correct:!1,feedback:"لا: لا يجوز لحاملي هذه الشارة المشاركة في القتال."},{text:"إنها مركبة الصليب الأحمر.",correct:!1,feedback:"شارة الصليب الأحمر صليب أحمر على أبيض، لا مثلث أزرق."},{text:"إنها علامة تجارية بلا معنى قانوني.",correct:!1,feedback:"لا: هذه الشارة مقررة في البروتوكول الأول لعام 1977."}]},caseStudy:[{prompt:"وضع متجر في حيّك شارة المثلث الأزرق على الخلفية البرتقالية على بابه ليبدو «آمنًا». أيّ رد صحيح؟",options:[{text:"هذا استخدام خاطئ؛ الشارة للدفاع المدني المأذون له فقط.",correct:!0,feedback:"صحيح: إساءة الاستخدام تُضعف احترام الشارة وقد تُضعف الحماية."},{text:"لا بأس، فكل أحد يستطيع استخدام شارة ملوّنة.",correct:!1,feedback:"لا: هذه الشارة مقررة بالقانون الدولي ولها وضع خاص."},{text:"لا بأس، فللمتجر دفاعه المدني الخاص.",correct:!1,feedback:"المتجر ليس منظمة دفاع مدني مأذونًا لها."}]},{prompt:"تريد تصحيح هذا الوضع. أيّ طريقة هي الأفضل والأسلم؟",options:[{text:"نبّه صاحب المتجر باحترام وأبلغ مديرية الدفاع المدني.",correct:!0,feedback:"صحيح: الاحترام وإبلاغ الجهة المختصة هما الطريق الصحيح."},{text:"انزع الشارة عن الباب بنفسك بالقوة.",correct:!1,feedback:"قد يسبب هذا مشكلة؛ والقرار للجهة المختصة."},{text:"انشر صورة المتجر على مواقع التواصل لإحراج صاحبه.",correct:!1,feedback:"التشهير لا يحل شيئًا؛ الطريق الرسمي أفضل."}]}],quiz:[{question:"ما الشارة الدولية للدفاع المدني؟",options:[{text:"مثلث أزرق متساوي الأضلاع على خلفية برتقالية.",correct:!0},{text:"صليب أحمر على خلفية بيضاء بحواف مستقيمة.",correct:!1},{text:"دائرة خضراء على خلفية صفراء مع نجمة.",correct:!1}],explanation:"تحدد المادة 66 من البروتوكول الأول المثلث الأزرق المتساوي الأضلاع على البرتقالي."},{question:"أيّ وثيقة منحت الدفاع المدني حماية خاصة؟",options:[{text:"البروتوكول الإضافي الأول لعام 1977.",correct:!0},{text:"اتفاقية جنيف الأولى لعام 1864.",correct:!1},{text:"قانون ARP البريطاني لعام 1937.",correct:!1}],explanation:"تقول اللجنة الدولية إن البروتوكول الأول لعام 1977 يحدد حماية الدفاع المدني (المواد 61–67)."},{question:"بحسب البروتوكول، الهجوم على أيّ مما يلي محظور؟",options:[{text:"منتسبو الدفاع المدني ومبانيه ومعداته.",correct:!0},{text:"مباني الدفاع المدني فقط دون منتسبيه.",correct:!1},{text:"المنتسبون في السلم فقط لا في الحرب.",correct:!1}],explanation:"تقول اللجنة الدولية إن مهاجمة منتسبي منظمات الدفاع المدني ومبانيها ومعداتها محظورة."},{question:"بحسب المادة 65، متى تنتهي حماية الدفاع المدني؟",options:[{text:"إذا استُخدم في أعمال ضارة وبعد إنذار لم يُستجب له.",correct:!0},{text:"كلما حمل المنتسبون سلاحًا فرديًا خفيفًا للدفاع عن أنفسهم.",correct:!1},{text:"كلما بدأ القتال داخل المدينة التي تعمل فيها الفرق.",correct:!1}],explanation:"لا تنتهي الحماية إلا بعد أعمال ضارة وإنذار بمهلة معقولة؛ وحمل سلاح خفيف لحفظ النظام أو الدفاع عن النفس لا يُعدّ ضارًا."},{question:"متى يُحمى العسكريون المخصصون للدفاع المدني؟",options:[{text:"إذا حملوا الشارة وعملوا على أرض دولتهم ولم يشاركوا في القتال.",correct:!0},{text:"في أي وقت وفي أي بلد، بالشارة أو دونها وبأي عمل.",correct:!1},{text:"فقط إذا شاركوا في القتال لحماية المدنيين.",correct:!1}],explanation:"تقول اللجنة الدولية إن حمايتهم مشروطة بحمل الشارة والعمل على أرض دولتهم وعدم المشاركة في القتال (المادة 67)."},{question:"أيّ تصرف يعبّر فعلًا عن احترام القانون الإنساني وفرق الدفاع المدني؟",options:[{text:"إفساح الطريق للفرق وعدم استخدام شارتها دون إذن.",correct:!0},{text:"التجمع حول الفرق في موقع الحادث لمشاهدة عملها.",correct:!1},{text:"وضع شارتها على سيارتك لتمرّ بسرعة.",correct:!1}],explanation:"الاحترام يعني إفساح الطريق للفرق وعدم إساءة استخدام شارتها؛ فالتجمع وسوء الاستخدام يعرقلان عملها."}]},{id:7,code:"HIS-SYM-107",icon:"ShieldCheck",accent:"#e8730c",title:"الشارة الدولية للدفاع المدني واليوم العالمي للدفاع المدني",subtitle:"المثلث الأزرق على البرتقالي: المعنى والحماية والاستخدام الصحيح",summary:"منح البروتوكول الإضافي الأول (1977) الدفاعَ المدني شارة دولية: مثلث أزرق متساوي الأضلاع على خلفية برتقالية. يوضح هذا الدرس ما تعنيه هذه الشارة، ومن يحق له استخدامها، ولماذا يُحظر إساءة استخدامها، ولماذا يوجد اليوم العالمي للدفاع المدني (1 آذار).",facts:[{label:"1931",value:"تأسيس جمعية «مناطق جنيف» في باريس لإيجاد أماكن آمنة للمدنيين."},{label:"1972",value:"في 1 آذار دخل دستور المنظمة الدولية للحماية المدنية (ICDO) حيز التنفيذ."},{label:"1977",value:"البروتوكول الإضافي الأول يجعل المثلث الأزرق على البرتقالي شارة الدفاع المدني."},{label:"2012",value:"المنظمة الدولية للحماية المدنية تفتتح اليوم العالمي للدفاع المدني رسميًا باحتفال."},{label:"كل عام، 1 آذار",value:"اليوم العالمي للدفاع المدني: يوم للتوعية والتقدير."}],blocks:[{heading:"كيف تبدو الشارة؟",body:"الشارة الدولية للدفاع المدني مثلث أزرق متساوي الأضلاع على خلفية برتقالية. وُضعت هذه الشارة في البروتوكول الإضافي الأول لعام 1977، وهو بروتوكول ملحق باتفاقيات جنيف. وتصف اللجنة الدولية للصليب الأحمر (ICRC) الشارة بالوصف نفسه. اختيرت ألوانها لتُرى بسهولة من بعيد ولا تختلط بغيرها من الشارات. وهذه الشارة ليست شعارًا للزينة، بل هي علامة حماية قانونية."},{heading:"ماذا تقول الشارة؟",body:`في وقت الحرب تقول هذه الشارة: «هذا الشخص أو هذا المبنى أو هذه المعدات لحماية المدنيين». ووفقًا للجنة الدولية للصليب الأحمر، لا يجوز لأطراف النزاع مهاجمة أفراد الدفاع المدني ومبانيه ومعداته. وتُظهر الشارة هذه الحماية:
• على ملابس الأفراد.
• على المركبات والمعدات.
• على المباني والملاجئ.
لكن الشارة وحدها لا تمنح الحماية: فالحماية تأتي من العمل الإنساني. وإذا استخدم شخص الشارة وقام بعمل حربي فإنه يفقد حمايته.`},{heading:"إساءة استخدام الشارة",body:"تقول اللجنة الدولية للصليب الأحمر إن على الدول أن تضمن فهم شارة الدفاع المدني وعدم إساءة استخدامها. فلو استطاع أي شخص وضع هذه الشارة على متجر أو سيارته أو إعلان، لفقد الناس ثقتهم بها ولفقدت الشارة معناها وقت الخطر. كما يجب ألا تُخلط الشارة بشارة الصليب الأحمر أو الهلال الأحمر: فتلك شارة الخدمات الطبية والحركة الدولية للصليب الأحمر، وللدفاع المدني شارته الخاصة. ويحدد القانون وتعليمات السلطة المختصة من يحق له استخدام الشارة وكيف."},{heading:"اليوم العالمي للدفاع المدني",body:`المنظمة الدولية للحماية المدنية (ICDO) منظمة حكومية دولية. يعود أصلها إلى جمعية «مناطق جنيف» التي تأسست عام 1931 في باريس، ودخل دستورها حيز التنفيذ في 1 آذار 1972. ولذلك أصبح 1 آذار اليوم العالمي للدفاع المدني، وتقول المنظمة إنه افتُتح رسميًا باحتفال عام 2012. وأهداف هذا اليوم هي:
• توعية الناس بالحماية الذاتية.
• تقدير أفراد الدفاع المدني ومتطوعيه.
• إظهار ضرورة الاستعداد قبل الكارثة.`},{heading:"ماذا تعني هذه الشارة لنا؟",body:"عندما ترى شارة الدفاع المدني فاعلم أن هذا الشخص أو المكان لمساعدة الناس. تعاون معهم باحترام وهدوء، وأفسح الطريق لمركباتهم. لا تضع الشارة على أغراضك الخاصة ولا تستخدم صورتها في الإعلانات. وفي المدرسة يكون يوم 1 آذار فرصة جيدة لفعالية توعوية: عرض رقم 115، وتمرين إخلاء، والتعريف بعمل الدفاع المدني. ويجب أن يكون كل نشاط باسم الدفاع المدني بالتنسيق مع مديرية الدفاع المدني."},{heading:"الشارة والبطاقة والإشارات",body:"الشارة طريقة واحدة فقط للتعرف إلى الدفاع المدني. وهدفها أن يُعرف الأفراد وأماكن الحماية بسهولة، ليعلم أطراف النزاع والناس أنهم للعمل الإنساني. وفي كثير من الدول يحمل أفراد الدفاع المدني بطاقة هوية أيضًا، ولمركباتهم ألوان وأصوات خاصة. والسؤال المهم هنا: من يحق له في بلدنا حمل الشارة وفي أي مكان؟ يحدد الجواب القانونُ وتعليماتُ السلطة المختصة، ويجب السؤال عنه في مديرية الدفاع المدني."}],warnings:["لا تضع شارة الدفاع المدني على متجر أو سيارة خاصة أو إعلان: فإساءة الاستخدام تُضعف ثقة الناس بها.","لا تنتحل صفة فرد من الدفاع المدني: فهذا يضر الناس ويعرقل المساعدة في الطوارئ."],tips:["تعرّف إلى الشارة جيدًا: مثلث أزرق على برتقالي، لا صليب أحمر.","نظّم في 1 آذار نشاطًا توعويًا في مدرستك أو عملك بالتنسيق مع الدفاع المدني.","عندما ترى مركبات الدفاع المدني أفسح لها الطريق ولا تعرقلها."],activity:{prompt:"يريد صاحب متجر وضع شارة الدفاع المدني على باب متجره ليثق به الناس. ماذا تقول له؟",options:[{text:"الشارة للدفاع المدني ويحددها القانون؛ ولا يجوز استخدامها للتجارة.",correct:!0,feedback:"صحيح: إساءة الاستخدام تُضعف معنى الشارة وثقة الناس بها."},{text:"لا بأس، يمكن لأي شخص استخدام الشارة شعارًا.",correct:!1,feedback:"لا: الشارة ليست شعارًا حرًّا؛ بل تدل على الحماية القانونية للدفاع المدني."},{text:"الأفضل أن يضع الصليب الأحمر لأن الناس يعرفونه أكثر.",correct:!1,feedback:"لا: الصليب الأحمر أيضًا شارة محمية للخدمات الطبية، لا للمتاجر."},{text:"إذا غيّر ألوانها فلا مشكلة.",correct:!1,feedback:"لا: الشارة المشابهة تُربك الناس؛ اسأل الدفاع المدني."}]},caseStudy:[{prompt:"تريد مدرستك إقامة احتفال يوم 1 آذار، وطلب منك المعلم وضع خطة. بماذا تبدأ؟",options:[{text:"بالتنسيق مع مديرية الدفاع المدني، وبهدف اليوم: التوعية والاستعداد.",correct:!0,feedback:"صحيح: النشاط باسم الدفاع المدني يحتاج إلى تنسيق."},{text:"بصنع ملابس عليها شارة الدفاع المدني لجميع الطلاب.",correct:!1,feedback:"لا: الشارة لأفراد الدفاع المدني؛ ويمكن للطلاب استخدام صور توعوية."},{text:"بكتابة تاريخ محلي من الذاكرة بلا مصدر.",correct:!1,feedback:"لا: المعلومات المحلية يجب أن تؤكدها المديرية."}]},{prompt:"في الاحتفال يسأل طالب: «لماذا الشارة زرقاء وبرتقالية وليست حمراء؟» كيف تجيب؟",options:[{text:"لتُرى من بعيد ولا تختلط بشارة الصليب الأحمر أو الهلال الأحمر.",correct:!0,feedback:"صحيح: كل شارة تدل على عمل حماية خاص."},{text:"لأنها ألوان علم دولة معينة.",correct:!1,feedback:"لا: الشارة دولية وليست لدولة بعينها."},{text:"لأن كل مديرية تختار ألوانها بنفسها.",correct:!1,feedback:"لا: الشكل والألوان محددة في بروتوكول 1977."}]}],quiz:[{question:"ما الشارة الدولية للدفاع المدني؟",options:[{text:"مثلث أزرق على خلفية برتقالية.",correct:!0},{text:"صليب أحمر على خلفية بيضاء.",correct:!1},{text:"دائرة خضراء على خلفية صفراء.",correct:!1}],explanation:"حدد البروتوكول الإضافي الأول (1977) المثلث الأزرق متساوي الأضلاع على البرتقالي."},{question:"أي وثيقة وضعت هذه الشارة؟",options:[{text:"البروتوكول الإضافي الأول لعام 1977.",correct:!0},{text:"إطار سنداي لعام 2015.",correct:!1},{text:"اتفاقية جنيف الأولى لعام 1864.",correct:!1}],explanation:"وُضعت الشارة في بروتوكول 1977، لا في اتفاقية 1864 ولا في إطار سنداي."},{question:"فرد يحمل الشارة على ملابسه يقوم بعمل حربي. ماذا يحدث لحمايته؟",options:[{text:"يفقد حمايته.",correct:!0},{text:"تبقى حمايته لأنه يحمل الشارة.",correct:!1},{text:"تتضاعف حمايته.",correct:!1}],explanation:"الحماية تأتي من العمل الإنساني، لا من الشارة وحدها."},{question:"متى اليوم العالمي للدفاع المدني؟",options:[{text:"1 آذار.",correct:!0},{text:"13 تشرين الأول.",correct:!1},{text:"12 تشرين الثاني.",correct:!1}],explanation:"تعتمد المنظمة 1 آذار يومًا عالميًا؛ ففيه دخل دستورها حيز التنفيذ عام 1972."},{question:"سيارة خاصة تحمل شارة الدفاع المدني وهي ليست للدفاع المدني. أي إجابة صحيحة؟",options:[{text:"هذه إساءة استخدام تُضعف الثقة بالشارة.",correct:!0},{text:"هذا جيد لأن الطريق يُفسح لها في الزحام.",correct:!1},{text:"هذا صحيح إذا كان صاحبها متطوعًا في السابق.",correct:!1}],explanation:"على الدول منع إساءة استخدام الشارة؛ ولا يستخدمها إلا من يأذن له القانون."},{question:"وفقًا للجنة الدولية، ما الذي لا يجوز لأطراف النزاع فعله؟",options:[{text:"مهاجمة أفراد الدفاع المدني ومبانيه ومعداته.",correct:!0},{text:"السماح للدفاع المدني بإطفاء الحرائق.",correct:!1},{text:"السماح للدفاع المدني بإخلاء الناس.",correct:!1}],explanation:"تقول اللجنة الدولية إنه لا يجوز مهاجمة أفراد الدفاع المدني ومبانيه ومعداته."}]},{id:8,code:"HIS-DRR-108",icon:"Compass",accent:"#2a7f62",title:"من الدفاع المدني إلى الحد من مخاطر الكوارث: هيوغو وسنداي",subtitle:"كيف انتقل العالم من الاستجابة إلى منع الخطر",summary:"بعد الحرب الباردة اتجه الدفاع المدني في دول كثيرة إلى جميع المخاطر. وجعل إطار هيوغو (2005–2015) وإطار سنداي (2015–2030) هذا التحول خطة للعالم كله: لا الاستجابة بعد الكارثة فقط، بل فهم الخطر والوقاية والإنذار المبكر وإعادة البناء بشكل أفضل.",facts:[{label:"2005، كانون الثاني",value:"اعتماد إطار عمل هيوغو في المؤتمر العالمي للحد من الكوارث في كوبي (هيوغو، اليابان)."},{label:"2005–2015",value:"هيوغو: خمس أولويات عمل للحد من خسائر الكوارث."},{label:"18 آذار 2015",value:"اعتماد إطار سنداي للحد من مخاطر الكوارث في سنداي (اليابان)."},{label:"2015–2030",value:"سنداي: سبع غايات وأربع أولويات عمل."}],blocks:[{heading:"تحوّل في التفكير",body:"في تاريخ الدفاع المدني كان العمل يبدأ غالبًا بعد بدء الخطر: الإنذار وقت الهجوم، وإطفاء الحريق، والإنقاذ من تحت الأنقاض. وما زالت هذه الأعمال مهمة. لكن الدول أدركت أن الكارثة ليست مجرد «حدث طبيعي»: فالخسائر الكبيرة تأتي من بناء مبانٍ ضعيفة في أماكن خطرة، ومن إنذار لا يصل إلى الناس، ومن غياب الاستعداد. ومن هنا نشأت فكرة جديدة: الحد من مخاطر الكوارث، أي أن نعرف الخطر ونقلّله قبل أن تأتي الكارثة."},{heading:"إطار عمل هيوغو (2005–2015)",body:`في كانون الثاني 2005، في المؤتمر العالمي للحد من الكوارث في مدينة كوبي بمحافظة هيوغو اليابانية، اعتمدت 168 دولة إطار عمل هيوغو. وكان هدفه خفضًا ملموسًا لخسائر الكوارث بحلول 2015. وأولوياته الخمس هي:
1. جعل الحد من المخاطر أولوية وطنية ومحلية.
2. تحديد المخاطر ورصدها وتحسين الإنذار المبكر.
3. المعرفة والتعليم لبناء ثقافة السلامة.
4. الحد من عوامل الخطر الأساسية.
5. تعزيز الاستعداد لاستجابة فعالة.`},{heading:"إطار سنداي (2015–2030)",body:`في 18 آذار 2015، في مؤتمر الأمم المتحدة العالمي الثالث في سنداي باليابان، اعتُمد إطار سنداي ليحل محل هيوغو. وهو لخمس عشرة سنة، وله سبع غايات وأربع أولويات عمل:
1. فهم مخاطر الكوارث.
2. تعزيز حوكمة مخاطر الكوارث.
3. الاستثمار في الحد من المخاطر من أجل القدرة على الصمود.
4. تعزيز الاستعداد لاستجابة فعالة و«إعادة البناء بشكل أفضل» في التعافي وإعادة الإعمار.
ومن غاياته زيادة توافر أنظمة الإنذار المبكر ومعلومات المخاطر للناس.`},{heading:"ماذا يعني هذا التحول للدفاع المدني؟",body:`لا يزال الدفاع المدني في الصف الأول للاستجابة، لكن عمله اتسع. ففي دول كثيرة يشارك الأفراد أنفسهم في:
• فحص السلامة والوقاية من الحريق قبل وقوعه.
• توعية الناس في المدارس وأماكن العمل.
• تمارين الإخلاء وخطط الطوارئ.
• دعم الإنذار المبكر مع الجهات الأخرى.
ويقول إطار سنداي إن للدولة الدور الأساسي، لكن المسؤولية مشتركة بين الجهات والقطاع الخاص والناس.`},{heading:"دورك في الحد من المخاطر",body:"يبدأ الحد من المخاطر من البيت. يمكنك أن تعرف مخاطر بيتك، وتضع خطة طوارئ للأسرة، وتجهز حقيبة طوارئ، وتحفظ رقم 115. وفي المدرسة ومكان العمل شارك في تمارين الإخلاء وأبلغ عن مشكلات السلامة. وعندما يصدر إنذار فاتبع القنوات الرسمية وتعليمات الدفاع المدني والسلطة المختصة فقط. وفكرة هيوغو وسنداي هي: كل شخص مستعد هو شخص لا يحتاج إلى إنقاذ ويستطيع مساعدة الآخرين."},{heading:"مِمَّ يتكون الخطر؟",body:"في فكرة الحد من المخاطر يتكون خطر الكارثة من ثلاثة أمور. الأول هو الحدث الخطِر، مثل الزلزال أو الفيضان أو الحريق. والثاني هو من وما يتعرض لهذا الحدث، مثل البيوت القريبة من النهر. والثالث هو الهشاشة، أي مدى قدرة الناس والمباني على الصمود. لا نستطيع إيقاف الزلزال، لكننا نستطيع تقوية المباني، وإبعاد الناس عن الأماكن الخطرة، وتقليل الهشاشة بالإنذار والتمرين. وهذا هو أساس هيوغو وسنداي."}],warnings:["لا تقل «الكارثة قدر ولا يمكن فعل شيء»: فكثير من الخسائر تقل بالاستعداد والوقاية.","لا تنشر تحذيرات غير رسمية: اتبع القنوات الرسمية والدفاع المدني فقط."],tips:["اكتب مخاطر بيتك وضع لكل منها طريقة للحد منها.","ضع خطة طوارئ للأسرة: نقطة التجمع وأرقام الهواتف وحقيبة الطوارئ.","شارك في تمارين الإخلاء بجدية: فهي استعداد حقيقي."],activity:{prompt:"يريد مجتمع بعد فيضان أن يعيد بناء بيوته في المكان المنخفض نفسه وبالطريقة نفسها. وفقًا لسنداي، أي طريق أفضل؟",options:[{text:"«إعادة البناء بشكل أفضل»: معرفة الخطر والبناء بشكل أكثر أمانًا وفق تعليمات السلطة المختصة.",correct:!0,feedback:"صحيح: هذه إحدى أولويات سنداي."},{text:"البناء نفسه بسرعة، لأن الفيضان لن يتكرر.",correct:!1,feedback:"لا: بلا تغيير ستتكرر الخسائر نفسها."},{text:"الانتظار حتى يقوم الدفاع المدني بكل العمل وحده.",correct:!1,feedback:"لا: سنداي يقول إن المسؤولية مشتركة."},{text:"وقف البناء وعدم وضع أي خطة.",correct:!1,feedback:"لا: الطريق هو التخطيط والبناء الأكثر أمانًا، لا التوقف."}]},caseStudy:[{prompt:"أنت في لجنة السلامة في قرية قرب نهر يرتفع ماؤه كل ربيع. ما أول عمل؟",options:[{text:"فهم الخطر: أي البيوت والطرق في خطر ومن يحتاج إلى مساعدة.",correct:!0,feedback:"صحيح: الأولوية الأولى في سنداي فهم الخطر."},{text:"شراء قوارب دون معرفة من يسكن أين.",correct:!1,feedback:"لا: بلا فهم للخطر لن تُستخدم المعدات بشكل صحيح."},{text:"انتظار الفيضان ثم اتخاذ القرار.",correct:!1,feedback:"لا: هذا تفكير الاستجابة القديم فقط، لا الحد من المخاطر."}]},{prompt:"أعدت اللجنة خريطة المخاطر. والآن يقول المسؤول عن المياه إن الماء قد يرتفع خلال يومين. ماذا تفعل اللجنة؟",options:[{text:"توصل الإنذار عبر القنوات الرسمية إلى كل البيوت، خاصة من يحتاج إلى مساعدة، وتعمل بتعليمات الدفاع المدني.",correct:!0,feedback:"صحيح: الإنذار المبكر لا ينفع إلا إذا وصل إلى الجميع وتحوّل إلى عمل."},{text:"تحتفظ بالإنذار حتى لا يخاف الناس.",correct:!1,feedback:"لا: الإنذار المخفي يحرم الناس من وقت الاستعداد."},{text:"تنشر رسالة مخيفة بلا تعليمات على مواقع التواصل.",correct:!1,feedback:"لا: يجب أن يكون الإنذار رسميًا وواضحًا ويقول للناس ماذا يفعلون."}]}],quiz:[{question:"متى وأين اعتُمد إطار هيوغو؟",options:[{text:"عام 2005 في كوبي باليابان.",correct:!0},{text:"عام 1977 في جنيف بسويسرا.",correct:!1},{text:"عام 2015 في باريس بفرنسا.",correct:!1}],explanation:"اعتُمد هيوغو في كانون الثاني 2005 في كوبي بمحافظة هيوغو."},{question:"ما الأولوية الأولى لإطار سنداي؟",options:[{text:"فهم مخاطر الكوارث.",correct:!0},{text:"شراء معدات الإنقاذ.",correct:!1},{text:"بناء ملاجئ تحت الأرض.",correct:!1}],explanation:"يبدأ سنداي بفهم الخطر لأن كل الأعمال الأخرى تُبنى عليه."},{question:"بعد زلزال أُعيد بناء مدرسة بالطريقة الضعيفة نفسها. هذا يخالف أي فكرة؟",options:[{text:"«إعادة البناء بشكل أفضل» في إعادة الإعمار.",correct:!0},{text:"الشارة الدولية للدفاع المدني.",correct:!1},{text:"اليوم العالمي للدفاع المدني.",correct:!1}],explanation:"يدعو سنداي إلى البناء بشكل أكثر أمانًا بعد الكارثة حتى لا تتكرر الخسائر."},{question:"وفقًا لسنداي، على من تقع مسؤولية الحد من المخاطر؟",options:[{text:"للدولة الدور الأساسي، لكنها مشتركة.",correct:!0},{text:"هي للدفاع المدني وحده.",correct:!1},{text:"هي للمنظمات الدولية وحدها.",correct:!1}],explanation:"يعطي سنداي الدور الأساسي للدولة ويشرك الجهات والقطاع الخاص والناس في المسؤولية."},{question:"أي عمل مثال على الحد من المخاطر قبل الكارثة؟",options:[{text:"تمرين إخلاء في المدرسة.",correct:!0},{text:"رفع الأنقاض بعد الانهيار.",correct:!1},{text:"إطفاء حريق قد اشتعل.",correct:!1}],explanation:"التمرين قبل الحادث يزيد الاستعداد؛ والعملان الآخران استجابة بعده."},{question:"كم غاية وكم أولوية في إطار سنداي؟",options:[{text:"سبع غايات وأربع أولويات.",correct:!0},{text:"خمس غايات وثلاث أولويات.",correct:!1},{text:"عشر غايات وأولويتان.",correct:!1}],explanation:"لسنداي (2015–2030) سبع غايات وأربع أولويات عمل؛ وكان لهيوغو خمس أولويات."}]},{id:9,code:"HIS-IRQ-109",icon:"Scale",accent:"#8a5a2b",title:"الدفاع المدني في العراق",subtitle:"قانون رقم 44 لسنة 2013 وكيف يُنظَّم العمل",summary:"في العراق يُنظَّم الدفاع المدني بقانون الدفاع المدني رقم 44 لسنة 2013. يوضح هذا الدرس كيف يعرّف القانون الدفاع المدني، ومن يرأسه، وكيف تعمل الجهات والناس معًا. ولا تُذكر إلا المعلومات المأخوذة من نص القانون؛ أما الأسئلة الأخرى فتُترك للمديرية.",facts:[{label:"27 تشرين الأول 2013",value:"صدور قانون الدفاع المدني رقم 44."},{label:"11 تشرين الثاني 2013",value:"نشر القانون."},{label:"المادة 1",value:"تعريف الدفاع المدني: حماية السكان والممتلكات في السلم والحرب والكوارث."},{label:"اليوم",value:"الدفاع المدني يتبع وزارة الداخلية؛ ورقم الطوارئ 115."}],blocks:[{heading:"قانون خاص بالدفاع المدني",body:"يقوم عمل الدفاع المدني في العراق على قانون خاص: قانون الدفاع المدني رقم 44 لسنة 2013. ووفقًا للنص المنشور صدر هذا القانون في 27 تشرين الأول 2013 ونُشر في 11 تشرين الثاني من السنة نفسها. والقانون مهم لأنه يحدد العمل والصلاحيات والمسؤوليات: من يقرر، ومن ينسّق، وما واجبات الناس. وبلا قانون تعمل كل جهة وقت الكارثة بطريقتها فيضيع الوقت والأرواح."},{heading:"كيف يعرّف القانون الدفاع المدني؟",body:`تعرّف المادة الأولى من القانون الدفاعَ المدني بأنه مجموعة الإجراءات التي تتخذها الأجهزة الرسمية والشعبية، عدا القوات المسلحة، لحماية السكان والممتلكات. وفي هذا التعريف ثلاثة أمور مهمة:
• يعمل في السلم والحرب والكوارث، لا في الحرب فقط.
• هو عمل الأجهزة الرسمية والشعبية معًا، لا عمل جهة واحدة.
• يختلف عن القوات المسلحة؛ فعمله إنساني وحمائي.
ويتفق هذا التعريف مع الفكرة الدولية التي رأيناها في الدروس السابقة.`},{heading:"من يتولى القيادة؟",body:"وفقًا لنص القانون فإن وزير الداخلية هو الرئيس الأعلى للدفاع المدني، والمحافظ هو رئيس الدفاع المدني في المحافظة. وهذا يبيّن أن الدفاع المدني عمل تنسيقي: على مستوى الدولة تحدد الوزارة الاتجاه، وعلى مستوى المحافظة يربط المحافظ بين الجهات المختلفة مثل الصحة والبلدية والشرطة والماء. وتقوم مديريات الدفاع المدني بالعمل اليومي في الإطفاء والإنقاذ والوقاية والتوعية. أما تفاصيل التنظيم الحالية فيجب تأكيدها من المصدر الرسمي."},{heading:"الناس والأجهزة الشعبية",body:`يذكر تعريف القانون «الأجهزة الشعبية» أيضًا. وهذا يعني أن الحماية ليست عمل الأفراد الرسميين وحدهم. فللناس والمدارس وأماكن العمل والمتطوعين دور أيضًا:
• الإبلاغ المبكر على الرقم 115.
• اتباع تعليمات السلامة في العمل والبيت.
• المشاركة في التمارين ودورات التوعية.
• المساعدة وقت الكوارث بتعليمات الدفاع المدني.
لكن مساعدة الناس يجب أن تكون منظمة: لا يدخل أحد النار أو الأنقاض بلا تدريب.`},{heading:"ما يحتاج بعدُ إلى تأكيد",body:"تاريخ الدفاع المدني في العراق قبل 2013 طويل، لكن هذا المساق لا يذكر إلا ما تؤكده المصادر الرسمية. أما الأسئلة مثل: القوانين السابقة للدفاع المدني، وتاريخ تأسيس المديرية العامة، والتعديلات الجديدة على القانون، فتُترك لمديرية الدفاع المدني. وإذا رأيت معلومات عن هذه الأسئلة على مواقع التواصل فلا تعتمد إلا المصدر الرسمي. وهذا أيضًا درس من دروس الدفاع المدني: المعلومة الصحيحة تحمي الأرواح، والمعلومة الخاطئة قد تضر."},{heading:"الدفاع المدني والجهات الأخرى",body:`لا يعمل الدفاع المدني وحده. ففي حادث كبير تعمل جهات كثيرة معًا، ولكل منها رقم طوارئ خاص:
• 115 للدفاع المدني: الحريق والإنقاذ والكوارث.
• 122 للإسعاف.
• 104 للشرطة.
وعندما تتصل قل بهدوء: المكان، وما الحادث، وعدد الأشخاص في خطر. وتنسيق هذه الجهات هو الهدف الذي يحدده القانون برئاسة المحافظ على مستوى المحافظة.`}],warnings:["لا تنشر معلومات غير مؤكدة عن قانون الدفاع المدني وتنظيمه.","لا تدخل النار أو الأنقاض بلا تدريب باسم «العمل الشعبي»: فالمساعدة تكون بتعليمات الدفاع المدني."],tips:["احفظ اسم القانون وسنته: قانون الدفاع المدني رقم 44 لسنة 2013.","لكل سؤال قانوني أو تنظيمي اسأل مديرية الدفاع المدني مباشرة.","شارك في دورات التوعية: فهي طريق الناس إلى دورهم في الدفاع المدني."],activity:{prompt:"يقول صديق: «الدفاع المدني للحرب فقط، ولا عمل له في السلم.» ماذا تقول وفقًا للقانون 44 لسنة 2013؟",options:[{text:"القانون يقول إنه يحمي السكان والممتلكات في السلم والحرب والكوارث.",correct:!0,feedback:"صحيح: المادة الأولى تذكر الأوقات الثلاثة."},{text:"صحيح، هو قوة قتالية.",correct:!1,feedback:"لا: القانون يستثنيه من القوات المسلحة."},{text:"يعمل في الحرائق فقط.",correct:!1,feedback:"لا: الحريق عمل واحد من أعمال كثيرة؛ والكوارث في التعريف أيضًا."},{text:"هو جهاز إداري فقط بلا عمل ميداني.",correct:!1,feedback:"لا: المديريات تقوم بالعمل الميداني في الإطفاء والإنقاذ."}]},caseStudy:[{prompt:"يحدث فيضان كبير في محافظة وتريد جهات كثيرة المساعدة. وفقًا للقانون، من رئيس الدفاع المدني على مستوى المحافظة؟",options:[{text:"المحافظ، الذي يربط بين الجهات.",correct:!0,feedback:"صحيح: يجعل القانون المحافظ رئيس الدفاع المدني في المحافظة."},{text:"كل جهة تقرر وحدها.",correct:!1,feedback:"لا: هذه هي المشكلة التي يريد القانون منعها."},{text:"منظمة دولية.",correct:!1,feedback:"لا: المنظمات الدولية تساعد، لكن القيادة للسلطة الوطنية."}]},{prompt:"يريد شباب كثيرون النزول إلى الماء للإنقاذ بأنفسهم. بوصفهم «أجهزة شعبية»، ما أفضل طريق؟",options:[{text:"أن يبلّغوا 115 ويساعدوا خارج الماء بتعليمات الدفاع المدني.",correct:!0,feedback:"صحيح: المساعدة الشعبية يجب أن تكون منظمة ولا تعرّض المساعدين للخطر."},{text:"أن ينزلوا جميعًا إلى الماء معًا.",correct:!1,feedback:"لا: مياه الفيضان تجرف كثيرًا من المساعدين أيضًا."},{text:"أن يصوّروا وينشروا على مواقع التواصل.",correct:!1,feedback:"لا: هذا يعرقل المنقذين ولا يساعد."}]}],quiz:[{question:"ما قانون الدفاع المدني في العراق؟",options:[{text:"القانون رقم 44 لسنة 2013.",correct:!0},{text:"القانون رقم 115 لسنة 2015.",correct:!1},{text:"القانون رقم 1977 لسنة 2005.",correct:!1}],explanation:"صدر قانون الدفاع المدني رقم 44 عام 2013."},{question:"وفقًا للقانون، من الرئيس الأعلى للدفاع المدني؟",options:[{text:"وزير الداخلية.",correct:!0},{text:"وزير التربية.",correct:!1},{text:"وزير الصحة.",correct:!1}],explanation:"يجعل نص القانون وزير الداخلية الرئيس الأعلى للدفاع المدني."},{question:"أي عبارة خاطئة وفق تعريف القانون؟",options:[{text:"الدفاع المدني جزء من القوات المسلحة.",correct:!0},{text:"يعمل في أوقات الكوارث.",correct:!1},{text:"تشارك فيه الأجهزة الشعبية أيضًا.",correct:!1}],explanation:"يقول التعريف «عدا القوات المسلحة»؛ فعمله إنساني."},{question:"يشتعل حريق في سوق. بصفتك من الناس، ما دورك الأول؟",options:[{text:"أبلغ 115 وابتعد بأمان.",correct:!0},{text:"ادخل النار لإخراج البضائع.",correct:!1},{text:"انتظر حتى يبلّغ شخص آخر.",correct:!1}],explanation:"الإبلاغ المبكر دور الناس؛ ودخول النار بلا تدريب يعرّض الحياة للخطر."},{question:"ترى على مواقع التواصل أن «قانون الدفاع المدني أُلغي». ماذا تفعل؟",options:[{text:"أتحقق من المصدر الرسمي أو المديرية.",correct:!0},{text:"أرسله بسرعة إلى كل أصدقائي.",correct:!1},{text:"أصدّقه لأن كثيرين نشروه.",correct:!1}],explanation:"المعلومة القانونية تؤخذ من المصدر الرسمي فقط."},{question:"وفقًا للقانون، من رئيس الدفاع المدني في كل محافظة؟",options:[{text:"المحافظ.",correct:!0},{text:"رئيس البلدية.",correct:!1},{text:"مدير المدرسة.",correct:!1}],explanation:"يجعل القانون المحافظ رئيس الدفاع المدني في المحافظة ليربط بين الجهات."}]},{id:10,code:"HIS-KRG-110",icon:"Building",accent:"#c0392b",title:"الدفاع المدني في إقليم كوردستان ودهوك",subtitle:"مديرية الدفاع المدني في دهوك اليوم: الأقسام والعمل ودور الناس",summary:"في إقليم كوردستان يتبع الدفاع المدني وزارة الداخلية، ولكل محافظة مديرية. يعرض هذا الدرس أقسام مديرية الدفاع المدني في دهوك بدليل تعريفي، ويبيّن كيف تعمل معًا. ولن يُضاف التاريخ المحلي إلا بعد تأكيد رسمي.",facts:[{label:"2013",value:"صدور قانون الدفاع المدني رقم 44 في العراق."},{label:"اليوم",value:"الدفاع المدني في إقليم كوردستان يتبع وزارة الداخلية."},{label:"اليوم",value:"الدليل التعريفي لمديرية دهوك يعرض 13 قسمًا."},{label:"كل يوم",value:"رقم طوارئ الدفاع المدني: 115."}],blocks:[{heading:"الدفاع المدني في إقليم كوردستان",body:"في إقليم كوردستان يتبع الدفاع المدني وزارة الداخلية، ولكل محافظة مديرية للدفاع المدني، مثل مديرية الدفاع المدني في دهوك. ومهمتها الأعمال الإنسانية التي رأيناها في الدروس السابقة: الإنذار والإطفاء والإنقاذ والإسعافات الأولية والإخلاء والتوعية. وشعار المديرية يقول: «معًا لحماية الإنسان والمجتمع والبيئة». أما أي القوانين والتعليمات (العراقية أو الإقليمية) تنطبق على عمل المديرية، فهو سؤال يجب أن يُجاب عنه رسميًا."},{heading:"أقسام مديرية دهوك",body:`يعرض الدليل التعريفي في هذا التطبيق 13 قسمًا (وهو دليل تعريفي، وليس الهيكل الإداري الرسمي):
1. المديرية والإدارة.
2. غرفة العمليات والطوارئ.
3. الإطفاء.
4. الإسعافات الأولية.
5. الإنقاذ البري.
6. المواد الخطرة.
7. الإنقاذ المائي.
8. الوقاية والتفتيش والسلامة.
9. الألغام والمقذوفات غير المنفلقة.
10. الإعلام والتوعية.
11. التعليم والتدريب.
12. اللوجستيات والآليات.
13. الإغاثة والإيواء.`},{heading:"كيف تعمل الأقسام معًا؟",body:"عندما تتصل بالرقم 115 تستقبل غرفة العمليات والطوارئ المعلومات وتنظمها وترسل الفرق المناسبة. وفي حريق منزل تسيطر فرقة الإطفاء على النار، ويُخرج الإنقاذ الناس، وتساعد الإسعافات الأولية المصابين ضمن مؤهلاتها وبالتنسيق مع الخدمات الطبية. وبعد الحادث يسجل قسم الوقاية والتفتيش الأسباب والنواقص، وتنشر التوعية والتعليم رسائل السلامة حتى لا يتكرر الحادث. وتبقي اللوجستيات المعدات والمركبات جاهزة. هذه سلسلة عمل: لا يستطيع قسم واحد وحده حماية الناس."},{heading:"الأقسام المتخصصة وحدود دور الناس",body:"بعض الأعمال للمختصين المدرَّبين والمخوَّلين فقط. فمثلًا يتولى عمل الألغام والمقذوفات غير المنفلقة مختصون مخوَّلون بالتنسيق مع السلطات المختصة. ودور الناس هنا واضح: لا تلمس، لا تقترب، أبعد الآخرين، وأبلغ 115. وكذلك في حوادث المواد الخطرة يبقى الناس بعيدين ويتبعون تعليمات الفريق. وفي الإنقاذ المائي لا يدخل أحد الماء بلا تدريب. والهدف من معرفة الأقسام أن تعرف من يفعل ماذا، لا أن تحل محلهم."},{heading:"التاريخ المحلي: بأمانة",body:"يريد كثيرون أن يعرفوا متى تأسست مديرية الدفاع المدني في دهوك وما الحوادث الكبرى في تاريخها. ولن يضيف هذا المساق هذه المعلومات إلا بعد تأكيد رسمي من المديرية، ولن تُكتب أسماء أشخاص. وإلى ذلك الحين يمكنك أن تسأل قسم الإعلام والتوعية. وبهذا يُكتب تاريخنا بأمانة: بمصدر وبلا زيادة. وهذا أيضًا تقدير لأفراد حموا الناس سنوات طويلة."},{heading:"الإبلاغ الصحيح على 115",body:`يبدأ عمل كل الأقسام باتصال جيد. عندما تتصل بالرقم 115:
• قل المكان بدقة: الحي والطريق وعلامة واضحة.
• قل ماذا حدث: حريق أو حادث طريق أو فيضان أو رائحة غاز.
• قل هل هناك أشخاص في خطر أو مصابون.
• لا تُنهِ المكالمة حتى يطلب منك الموظف ذلك.
وإذا كنت في مكان آمن فابقَ فيه ليجدك الفريق. هذه المعلومات تساعد غرفة العمليات على إرسال الفريق المناسب بسرعة.`}],warnings:["لا تلمس الألغام أو المقذوفات غير المنفلقة ولا تقترب منها: فهذا عمل المختصين المخوَّلين.","لا تنشر تاريخًا أو أسماء باسم المديرية ما لم تؤكَّد رسميًا."],tips:["احفظ 115 وقل بهدوء: المكان، وما الحادث، وهل هناك أشخاص في خطر.","لتمرين أو زيارة توعوية في المدرسة اطلب ذلك من قسم التعليم والتدريب.","شاهد دليل الأقسام في التطبيق لتعرف من يفعل ماذا."],activity:{prompt:"ترى في الطريق جسمًا معدنيًا مجهولًا قد يكون مقذوفًا. وفقًا لعمل أقسام المديرية، ماذا تفعل؟",options:[{text:"لا ألمسه ولا أقترب، أبعد الناس، وأبلغ 115.",correct:!0,feedback:"صحيح: ثم يتولى المختصون المخوَّلون عملهم."},{text:"أحمله إلى مركز الدفاع المدني.",correct:!1,feedback:"لا: حمله قد يسبب انفجارًا؛ لا تلمسه أبدًا."},{text:"أصوّره عن قرب وأنشر الصورة.",correct:!1,feedback:"لا: الاقتراب خطر؛ والإبلاغ على 115 هو الطريق الصحيح."},{text:"أضربه بحجر لأعرف هل هو فارغ.",correct:!1,feedback:"لا: قد يسبب ذلك انفجارًا؛ فهذا عمل المختصين فقط."}]},caseStudy:[{prompt:"في مصنع تنبعث رائحة كيميائية قوية ويسعل بعض العمال. أنت مسؤول السلامة. ما أول عمل؟",options:[{text:"أخرج الناس نحو الهواء النقي وأبلغ 115.",correct:!0,feedback:"صحيح: سترسل غرفة العمليات فريق المواد الخطرة."},{text:"ادخل بنفسك لترى مصدر الرائحة.",correct:!1,feedback:"لا: بلا معدات وقاية قد تصبح أنت ضحية أيضًا."},{text:"أغلق النوافذ وتابع العمل.",correct:!1,feedback:"لا: هذا يزيد الخطر."}]},{prompt:"وصل فريق الدفاع المدني ويسأل قائده. أي معلومات تعطيه؟",options:[{text:"مكان الرائحة، والمواد الموجودة، وعدد العمال، وهل بقي أحد في الداخل.",correct:!0,feedback:"صحيح: هذه المعلومات تحمي الفريق وتسرّع الإنقاذ."},{text:"تقترح أن تدخل مع الفريق بنفسك.",correct:!1,feedback:"لا: للفريق معدات وقاية؛ وأنت تبقى في الخارج."},{text:"تقول لا مشكلة حتى لا يُغلق المصنع.",correct:!1,feedback:"لا: إخفاء المعلومات يعرّض الأرواح للخطر."}]}],quiz:[{question:"في إقليم كوردستان، لأي وزارة يتبع الدفاع المدني؟",options:[{text:"وزارة الداخلية.",correct:!0},{text:"وزارة التربية.",correct:!1},{text:"وزارة البلديات.",correct:!1}],explanation:"يتبع الدفاع المدني وزارة الداخلية ولكل محافظة مديرية."},{question:"عندما تتصل بالرقم 115، أي قسم يستقبل المعلومات أولًا؟",options:[{text:"غرفة العمليات والطوارئ.",correct:!0},{text:"قسم اللوجستيات والآليات.",correct:!1},{text:"قسم التعليم والتدريب.",correct:!1}],explanation:"تستقبل غرفة العمليات المعلومات وتنظمها وترسل الفرق المناسبة."},{question:"بعد حريق، أي قسم يسجل الأسباب ونواقص السلامة؟",options:[{text:"الوقاية والتفتيش والسلامة.",correct:!0},{text:"الإنقاذ المائي والقوارب.",correct:!1},{text:"الإغاثة والإيواء والدعم.",correct:!1}],explanation:"يسجل قسم الوقاية والتفتيش النواقص حتى لا يتكرر الحادث."},{question:"يريد صديقك رفع جسم غير منفلق عن الأرض. أي إجابة صحيحة؟",options:[{text:"امنعه، وابتعدا، وأبلغ 115.",correct:!0},{text:"دعه يرفعه ببطء وبكلتا يديه.",correct:!1},{text:"اغسلاه بالماء لقراءة ما عليه.",correct:!1}],explanation:"هذا عمل المختصين المخوَّلين؛ والناس لا يلمسون ولا يقتربون بل يبلّغون."},{question:"ما دليل الأقسام في التطبيق؟",options:[{text:"دليل تعريفي، وليس الهيكل الإداري الرسمي.",correct:!0},{text:"الهيكل الرسمي والنهائي للمديرية بكل تفاصيله.",correct:!1},{text:"قائمة بأسماء الأفراد وأرقام هواتفهم.",correct:!1}],explanation:"يقول التطبيق نفسه إنه دليل تعريفي، وليس الهيكل الإداري الرسمي."},{question:"في فيضان ترى شخصًا في الماء، وليس لديك تدريب على الإنقاذ المائي. ماذا تفعل؟",options:[{text:"أبلغ 115 وأرمي له شيئًا من خارج الماء.",correct:!0},{text:"أنزل الماء بسرعة وأسحبه.",correct:!1},{text:"أصوّر فيديو لمواقع التواصل.",correct:!1}],explanation:"الإنقاذ المائي عمل الفرق المدرَّبة؛ والمساعدة من خارج الماء أكثر أمانًا."}]},{id:11,code:"HIS-LES-111",icon:"AlertTriangle",accent:"#6b4f9e",title:"دروس من كوارث كبرى موثّقة",subtitle:"ماذا تعلّم الدفاع المدني من كل كارثة؟",summary:"كل كارثة كبرى، بآلامها وخسائرها، تعطينا درسًا. يعرض هذا الدرس أربعة أحداث حقيقية موثّقة بمصادر: كارثة الغاز في بوبال (1984)، وتسونامي المحيط الهندي (2004)، وزلزال الحدود العراقية الإيرانية (2017)، وزلزالي تركيا وسوريا (2023). وسنرى لكل منها ماذا تعلّم الدفاع المدني.",facts:[{label:"1984، 2–3 كانون الأول",value:"بوبال (الهند): تسرّب غاز سام من مصنع مبيدات."},{label:"2004، 26 كانون الأول",value:"تسونامي المحيط الهندي يصيب 17 دولة في آسيا وأفريقيا."},{label:"2017، 12 تشرين الثاني",value:"زلزال بقوة 7.3 على الحدود العراقية الإيرانية."},{label:"2023، 6 شباط",value:"زلزالان بقوة 7.8 و7.5 في تركيا، مع خسائر كبيرة في تركيا وسوريا."}],blocks:[{heading:"لماذا ندرس الكوارث السابقة؟",body:"كُتب تاريخ الدفاع المدني في معظمه من الكوارث. فبعد كل كارثة يسأل المختصون: ما الذي نجح؟ وما الذي لم ينجح؟ وما الذي يجب تغييره؟ وتصبح الإجابات قوانين وتعليمات وتدريبًا ومعدات جديدة. وفي هذا الدرس ننظر باحترام للضحايا إلى أربعة أحداث موثّقة. ولا نذكر أرقام الوفيات المختلف فيها؛ فهدفنا الدرس لا التخويف. وفي النهاية نربط كل درس بحياتنا اليومية: في البيت والمدرسة ومكان العمل."},{heading:"بوبال 1984: المخاطر الصناعية",body:`في ليلة 2 إلى 3 كانون الأول 1984 تسرّب غاز سام (ميثيل أيزوسيانات) من مصنع مبيدات في مدينة بوبال بالهند. فمات الآلاف وأُصيب كثيرون غيرهم بأمراض طوال حياتهم. ولم يكن سكان المنطقة القريبة من المصنع يعرفون ما هذا الغاز ولا ماذا يفعلون. ودروس الدفاع المدني:
• يجب أن يعرف السكان قرب المصانع الخطر وطريقة الحماية.
• يجب أن تكون للمصنع خطة طوارئ وتنسيق مع الدفاع المدني.
• الإنذار المبكر والإخلاء ينقذان الأرواح.
• البناء السكني قرب المصانع الخطرة يزيد الخطر.`},{heading:"تسونامي 2004: الإنذار المبكر",body:"في 26 كانون الأول 2004 أحدث زلزال كبير في قاع المحيط الهندي تسونامي أصاب، بحسب NOAA، 17 دولة في آسيا وأفريقيا. وفي أماكن كثيرة لم يتلقَّ الناس إنذارًا أو لم يعرفوا ماذا يفعلون. وتقول NOAA إن قدرات الإنذار تحسّنت كثيرًا منذ ذلك الحين. والدرس الأساسي أن الإنذار ليس جهازًا فقط: يجب أن يصل إلى جميع الناس بلغة واضحة، وأن يعرف الناس ماذا يفعلون عند الإنذار. وهذه هي الفكرة التي استُخدمت لاحقًا في أنظمة الإنذار المبكر الحديثة."},{heading:"زلزالا 2017 و2023: المباني والإنقاذ",body:`في 12 تشرين الثاني 2017، بحسب هيئة المسح الجيولوجي الأمريكية (USGS)، وقع زلزال بقوة 7.3 على الحدود العراقية الإيرانية وشُعر به في منطقتنا أيضًا. وفي 6 شباط 2023 وقع زلزالان بقوة 7.8 و7.5 في جنوب تركيا وسبّبا خسائر كبيرة جدًا في تركيا وسوريا. ودروس الدفاع المدني:
• المباني المشيّدة وفق تعليمات البناء الصحيحة تحمي الأرواح.
• «انخفض، واحتمِ، وتمسّك» أثناء الاهتزاز.
• تحدث هزات ارتدادية؛ فلا تعد إلى المباني المتضررة.
• الإنقاذ من تحت الأنقاض عمل فرق مدرَّبة ويحتاج إلى تنسيق.`},{heading:"الدروس المشتركة",body:`إذا نظرنا إلى الكوارث الأربع تتكرر الدروس نفسها:
1. معرفة الخطر قبل الكارثة: ما المخاطر من حولنا.
2. إنذار مبكر يصل إلى الجميع ويكون واضحًا.
3. بناء وتخطيط آمنان: مبانٍ قوية بعيدة عن المخاطر.
4. استعداد الناس: التمارين وخطة الأسرة والرقم 115.
5. التنسيق بين الجهات والإنقاذ المنظم.
وهذه هي أولويات هيوغو وسنداي التي رأيناها في الدرس 8: الكارثة تعطي درسًا قاسيًا، وواجبنا ألا ننساه.`},{heading:"كيف يصبح الدرس عملًا؟",body:"لا يُتعلَّم الدرس بالكتابة وحدها. فبعد كل حادث يجب أن تسأل فرق الدفاع المدني بصدق: ما الذي كان جيدًا وما الذي يجب تحسينه، ثم تحدّث الخطط والتمارين والمعدات. والطريقة نفسها تُستخدم في المدرسة ومكان العمل: بعد كل تمرين إخلاء اسأل: كم استغرق الوقت، ومن تأخر، وأي باب كان مغلقًا. وإذا نسينا هذه الدروس فستكرر الكارثة الخسائر نفسها."}],warnings:["لا تعد بعد الزلزال إلى مبنى متضرر حتى تسمح السلطة المختصة: فالهزات الارتدادية قد تهدمه.","إذا جاءت رائحة غاز مجهول من مصنع فلا تذهب لترى: ابتعد وأبلغ 115.","لا تنشر أرقامًا غير مؤكدة للضحايا: احترم الضحايا واستخدم المصدر الرسمي."],tips:["اعرف هل يوجد قرب بيتك مصنع أو نهر أو أماكن خطرة.","تدرّب مع أسرتك على «انخفض، واحتمِ، وتمسّك».","عندما يصدر إنذار رسمي فاعمل به بسرعة وأوصله إلى من يحتاج إلى مساعدة."],activity:{prompt:"رتّب: ما الترتيب الزمني لهذه الكوارث الأربع؟",options:[{text:"بوبال، تسونامي المحيط الهندي، زلزال الحدود العراقية الإيرانية، زلزالا تركيا وسوريا.",correct:!0,feedback:"صحيح: 1984، 2004، 2017، 2023."},{text:"تسونامي المحيط الهندي، بوبال، زلزالا تركيا وسوريا، زلزال الحدود العراقية الإيرانية.",correct:!1,feedback:"لا: بوبال (1984) قبل التسونامي (2004)، و2017 قبل 2023."},{text:"زلزال الحدود العراقية الإيرانية، بوبال، تسونامي المحيط الهندي، زلزالا تركيا وسوريا.",correct:!1,feedback:"لا: زلزال الحدود كان عام 2017، بعد بوبال والتسونامي."},{text:"زلزالا تركيا وسوريا، تسونامي المحيط الهندي، بوبال، زلزال الحدود العراقية الإيرانية.",correct:!1,feedback:"لا: زلزالا تركيا وسوريا عام 2023 هما الأحدث."}]},caseStudy:[{prompt:"في مدينة، مصنع مواد كيميائية قرب حي جديد. تسألك البلدية: أي درس من كارثة بوبال هو الأهم هنا؟",options:[{text:"خطة طوارئ للمصنع بالتنسيق مع الدفاع المدني، وتوعية سكان الحي.",correct:!0,feedback:"صحيح: في بوبال لم يعرف الناس ماذا يفعلون."},{text:"لا شيء لأن المصنع جديد ولن تحدث مشكلات.",correct:!1,feedback:"لا: المعدات الجديدة قد تتعطل أيضًا؛ والاستعداد ضروري."},{text:"زيادة سيارات الإطفاء فقط.",correct:!1,feedback:"لا: الغاز السام لا يُعالج بالإطفاء وحده؛ بل يلزم الإنذار والإخلاء."}]},{prompt:"اعتمدت البلدية الخطة، وتسأل الآن: من تسونامي 2004، كيف يصل الإنذار إلى جميع سكان الحي؟",options:[{text:"عبر عدة قنوات رسمية، بلغة واضحة تقول ماذا يفعلون، وبتمارين متكررة.",correct:!0,feedback:"صحيح: يجب أن يصل الإنذار إلى الجميع وأن يعرف الناس ماذا يفعلون."},{text:"بصفارة واحدة فقط بلا تمارين ولا شرح.",correct:!1,feedback:"لا: إذا لم يعرف الناس معنى الصوت فلن ينفع الإنذار."},{text:"برسالة بلغة أجنبية لا يفهمها الناس.",correct:!1,feedback:"لا: يجب أن يكون الإنذار بلغة الناس وواضحًا."}]}],quiz:[{question:"ما الدرس الأبرز من كارثة بوبال (1984)؟",options:[{text:"خطة الطوارئ وتوعية السكان قرب المصانع الخطرة.",correct:!0},{text:"بناء المباني على الجبال العالية في كل مكان.",correct:!1},{text:"استخدام الماء على كل الحرائق بلا تمييز.",correct:!1}],explanation:"في بوبال لم يعرف الناس ما الغاز ولا ماذا يفعلون؛ والخطة والتوعية تحميان الأرواح."},{question:"ما الدرس الأساسي من تسونامي 2004؟",options:[{text:"الإنذار المبكر يجب أن يصل إلى الجميع وأن يكون واضحًا.",correct:!0},{text:"التسونامي يؤثر في دولة واحدة فقط.",correct:!1},{text:"لا حاجة إلى إنذار لأن الماء يأتي ببطء.",correct:!1}],explanation:"تقول NOAA إن التسونامي أصاب 17 دولة وإن الإنذار تحسّن كثيرًا منذ ذلك الحين."},{question:"بعد زلزال في مبناك تشققات وتريد العودة لإحضار أغراضك. أي قرار صحيح؟",options:[{text:"ابقَ في الخارج حتى تسمح السلطة المختصة.",correct:!0},{text:"عد بسرعة قبل أن تأتي هزة أخرى.",correct:!1},{text:"عد إذا بدت تشققات الجدران صغيرة.",correct:!1}],explanation:"الهزات الارتدادية قد تهدم مبنى ضعيفًا."},{question:"ما قوة زلزال الحدود العراقية الإيرانية عام 2017؟",options:[{text:"7.3.",correct:!0},{text:"5.1.",correct:!1},{text:"9.2.",correct:!1}],explanation:"تقول USGS إن زلزال 12 تشرين الثاني 2017 كان بقوة 7.3."},{question:"أنت داخل غرفة أثناء الزلزال. ما أول عمل؟",options:[{text:"انخفض، واحتمِ، وتمسّك.",correct:!0},{text:"انزل بسرعة بالمصعد.",correct:!1},{text:"قف قرب النافذة لترى.",correct:!1}],explanation:"أثناء الاهتزاز تكون الحماية في المكان أكثر أمانًا من الركض؛ والمصعد والنوافذ خطرة."},{question:"أي درس مشترك بين الكوارث الأربع؟",options:[{text:"الاستعداد ومعرفة الخطر قبل الكارثة.",correct:!0},{text:"الكوارث تقع في الدول البعيدة فقط.",correct:!1},{text:"لا توجد طريقة لتقليل الخسائر.",correct:!1}],explanation:"معرفة الخطر والإنذار والبناء الآمن والاستعداد تتكرر في الأربع كلها."}]},{id:12,code:"HIS-FUT-112",icon:"Satellite",accent:"#1f6fb2",title:"مستقبل الدفاع المدني: التقنية والإنذار المبكر وصمود المجتمع",subtitle:"خاتمة المساق: من التاريخ إلى المستقبل",summary:"هذا هو الدرس الأخير في مساق تاريخ الدفاع المدني. يبيّن كيف تغيّر التقنية والإنذار المبكر عمل الدفاع المدني، ولماذا يبقى صمود المجتمع أساسًا، ويقدّم خلاصة المساق كله: من حرائق المدن إلى سنداي.",facts:[{label:"1977",value:"البروتوكول الأول يمنح الدفاع المدني حماية وشارة دولية."},{label:"2005",value:"إطار هيوغو: الحد من مخاطر الكوارث يصبح أولوية عالمية."},{label:"2015",value:"إطار سنداي للأعوام 2015–2030."},{label:"2022",value:"الأمم المتحدة تدعو إلى «الإنذار المبكر للجميع»."},{label:"2027",value:"الهدف: حماية كل سكان العالم بأنظمة الإنذار المبكر."},{label:"2030",value:"نهاية مدة إطار سنداي."}],blocks:[{heading:"الإنذار المبكر للجميع",body:`في عام 2022، في اليوم العالمي للأرصاد الجوية، دعا الأمين العام للأمم المتحدة إلى مبادرة «الإنذار المبكر للجميع». ووفقًا للمنظمة العالمية للأرصاد الجوية (WMO) فإن الهدف أن يكون كل سكان العالم محميين بأنظمة الإنذار المبكر بحلول نهاية 2027. ولهذه الأنظمة أربع ركائز:
1. معرفة مخاطر الكوارث.
2. الرصد والتحليل والتنبؤ.
3. نشر الإنذار وإيصاله.
4. الاستعداد وقدرات الاستجابة.
وتبيّن الركيزة الرابعة أن الإنذار لا ينفع بلا ناس مستعدين.`},{heading:"التقنية في خدمة الحماية",body:`غيّرت التقنية عمل الدفاع المدني وما زالت تغيّره. ومن الأمثلة:
• يصل الإنذار إلى الناس عبر الهواتف المحمولة ووسائل الإعلام.
• تساعد صور الأقمار الصناعية والخرائط الرقمية في معرفة أماكن الفيضانات وحرائق الغابات.
• تساعد الطائرات المسيّرة في البحث في الأماكن الصعبة.
• توصل تطبيقات التعليم، مثل هذا التطبيق، التوعية إلى الجميع.
لكن التقنية قد تتعطل: تنقطع الكهرباء وتتوقف الشبكة. لذلك للخطة الجيدة دائمًا طريق بديل، ويبقى الإنسان المدرَّب أساس العمل. فكل جهاز جديد يحتاج إلى تدريب وصيانة وخطة، والقرار الأخير في موقع الحادث يبقى للإنسان المدرَّب الذي يرى الوضع ويعمل بمسؤولية. لذلك يجب أن يرافق إدخالَ التقنية تعليمُ الأفراد والناس.`},{heading:"صمود المجتمع",body:`الصمود هو قدرة المجتمع على تجاوز الكارثة بأقل الخسائر والعودة سريعًا إلى حياته. وفي تاريخ كل الكوارث كان أول المساعدين غالبًا الجيران والأسرة قبل وصول الفرق الرسمية. لذلك يرتبط مستقبل الدفاع المدني بمجتمعات مستعدة:
• للأسر خطة طوارئ وحقيبة طوارئ.
• تجري المدارس وأماكن العمل تمارين الإخلاء.
• يعمل المتطوعون المدرَّبون بالتنسيق مع الدفاع المدني.
• يهتم الجيران بكبار السن والمرضى وذوي الاحتياجات الخاصة.`},{heading:"خلاصة المساق",body:`رأينا في هذا المساق تاريخ الدفاع المدني مرحلة بعد مرحلة:
1. ما الدفاع المدني: أعمال إنسانية لحماية المدنيين.
2. حماية المدن قديمًا: الحراسة من الحريق وإغاثة الكوارث.
3. الحرب العالمية الأولى: بداية الحماية من الغارات الجوية.
4. الحرب العالمية الثانية: الملاجئ والصفارات والمتطوعون.
5. الحرب الباردة: التخطيط والإنذار.
6. القانون الإنساني وحماية الدفاع المدني.
7. الشارة الدولية واليوم العالمي.
8. هيوغو وسنداي: من الاستجابة إلى الحد من المخاطر.
9. الدفاع المدني في العراق.
10. الدفاع المدني في إقليم كوردستان ودهوك.
11. دروس من الكوارث الكبرى.
12. المستقبل: التقنية والإنذار والصمود.`},{heading:"الخيط الذي يجمع التاريخ كله",body:"إذا نظرنا إلى هذا التاريخ كله نجد هدفًا واحدًا لم يتغير: حماية حياة الناس. تغيّرت الأدوات من دلاء الماء إلى الطائرات المسيّرة، وتغيّرت المخاطر من الغارات الجوية إلى تغيّر المناخ. لكن الأسس بقيت نفسها: معرفة الخطر، والإنذار المبكر، والاستعداد، والتنسيق، والعمل الإنساني. والآن أنت أيضًا جزء من هذا التاريخ: بالرقم 115، وبخطة أسرتك، وبالمشاركة في التمارين، وبنقل التوعية إلى الآخرين. كل شخص مستعد هو عون للدفاع المدني."}],warnings:["لا تعتمد على الهاتف وحده: إذا توقفت الشبكة فيجب أن يكون هناك طريق ثانٍ للإنذار والاتصال.","لا تطيّر طائرة مسيّرة فوق مكان الحادث: فهي تعرقل عمل فرق الإنقاذ وطائراتها."],tips:["فعّل الإنذارات الرسمية على هاتفك واستقبلها من القنوات الرسمية فقط.","ضع راديو يعمل بالبطارية في حقيبة الطوارئ.","شارك ما تعلمته في هذا المساق مع أسرتك وأصدقائك."],activity:{prompt:"أثناء فيضان توقفت شبكة الهاتف في حيّك. أي درس من هذا الدرس ينطبق هنا؟",options:[{text:"للخطة الجيدة طريق بديل: راديو بالبطارية ونقطة تجمع متفق عليها.",correct:!0,feedback:"صحيح: قد تتعطل التقنية، فيجب أن يكون للخطة طريق بديل."},{text:"انتظر عودة الشبكة ولا تفعل شيئًا.",correct:!1,feedback:"لا: قد لا يكون هناك وقت؛ والطريق البديل ضروري."},{text:"قُد السيارة عبر الماء لتجد شبكة.",correct:!1,feedback:"لا: القيادة في مياه الفيضان خطرة جدًا."},{text:"صدّق أي إشاعة يقولها الجيران.",correct:!1,feedback:"لا: اتبع القنوات الرسمية فقط، مثل الراديو."}]},caseStudy:[{prompt:"تريد مدرستك تنظيم «يوم تاريخ الدفاع المدني» وأنت مسؤول جدار التاريخ. أي ترتيب صحيح؟",options:[{text:"البروتوكول الأول (1977)، هيوغو (2005)، سنداي (2015)، الإنذار المبكر للجميع (2022).",correct:!0,feedback:"صحيح: هذا هو الترتيب الزمني."},{text:"سنداي (2015)، البروتوكول الأول (1977)، الإنذار المبكر للجميع (2022)، هيوغو (2005).",correct:!1,feedback:"لا: انظر إلى السنوات بالترتيب؛ 1977 الأقدم."},{text:"هيوغو (2005)، البروتوكول الأول (1977)، سنداي (2015)، الإنذار المبكر للجميع (2022).",correct:!1,feedback:"لا: البروتوكول (1977) قبل هيوغو (2005)."}]},{prompt:"في نهاية الاحتفال يسأل مدير المدرسة: «ماذا يستطيع الطلاب أن يفعلوا اليوم ليكونوا جزءًا من هذا التاريخ؟» ما أفضل إجابة؟",options:[{text:"يحفظون 115، ويضعون خطة الأسرة، ويشاركون في التمارين، وينقلون التوعية إلى الآخرين.",correct:!0,feedback:"صحيح: صمود المجتمع يبدأ من الأشخاص المستعدين."},{text:"لا شيء؛ فالحماية عمل الفرق الرسمية وحدها.",correct:!1,feedback:"لا: في كل الكوارث كان أول المساعدين غالبًا من الناس."},{text:"تنزيل تطبيق فقط دون أي تمرين.",correct:!1,feedback:"لا: التقنية تساعد، لكن التمرين والخطة هما الأساس."}]}],quiz:[{question:"وفقًا للمنظمة العالمية للأرصاد، ما هدف «الإنذار المبكر للجميع»؟",options:[{text:"حماية الجميع بالإنذار المبكر بحلول نهاية 2027.",correct:!0},{text:"بناء ملاجئ تحت الأرض في كل المدن بحلول 2030.",correct:!1},{text:"توحيد أرقام الطوارئ برقم عالمي واحد بحلول 2025.",correct:!1}],explanation:"تقول المنظمة إن الهدف حماية كل سكان العالم بأنظمة الإنذار المبكر بحلول نهاية 2027."},{question:"ما الركيزة الرابعة لأنظمة الإنذار المبكر؟",options:[{text:"الاستعداد وقدرات الاستجابة.",correct:!0},{text:"شراء هواتف جديدة للجميع.",correct:!1},{text:"بناء محطات تلفزيون جديدة.",correct:!1}],explanation:"لا ينفع الإنذار بلا ناس مستعدين؛ لذلك الركيزة الرابعة هي الاستعداد."},{question:"هناك حريق ويريد جارك تطيير طائرة مسيّرة فوقه للتصوير. ماذا تقول؟",options:[{text:"لا تطيّرها؛ فهي تعرقل فرق الإنقاذ.",correct:!0},{text:"طيّرها؛ فالصور ستساعد رجال الإطفاء.",correct:!1},{text:"طيّرها لكن ليلًا فقط.",correct:!1}],explanation:"الطائرات الخاصة قد تعرقل فرق الإنقاذ وطائراتها؛ اترك المجال للفرق الرسمية."},{question:"ما «صمود المجتمع»؟",options:[{text:"قدرة المجتمع على تجاوز الكارثة بأقل الخسائر والعودة سريعًا إلى الحياة.",correct:!0},{text:"بناء أسوار عالية حول المدينة كلها لمنع وصول الكوارث.",correct:!1},{text:"ترك كل العمل والمسؤولية للدولة والمنظمات الأجنبية وحدها.",correct:!1}],explanation:"يُبنى الصمود باستعداد الأسر والمدارس وأماكن العمل والجيران."},{question:"أي هدف بقي ثابتًا في كل تاريخ الدفاع المدني؟",options:[{text:"حماية حياة الناس.",correct:!0},{text:"استخدام المعدات نفسها.",correct:!1},{text:"الاستجابة وقت الحرب فقط.",correct:!1}],explanation:"تغيّرت المعدات والمخاطر، لكن الهدف بقي حماية حياة الناس."},{question:"تصلك رسالة على الهاتف تقول إن فيضانًا قريب، لكنها من مصدر مجهول. ما أول عمل؟",options:[{text:"أتحقق من قناة رسمية وأستعد.",correct:!0},{text:"أرسلها بسرعة للجميع دون تحقق.",correct:!1},{text:"أتجاهلها لأن كل الرسائل كاذبة.",correct:!1}],explanation:"يؤخذ الإنذار من القنوات الرسمية فقط، لكن الاستعداد لا يضر."}]}],t={lessons:e};export{t as default,e as lessons};
